pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1148: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but heavily penalize leaving a gap that cannot fit next_item_size.
    // Reward bins that become "perfect fits" for the next item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": If the remaining space is too small for next_item_size,
    // we penalize it unless it's a very tight fit (post_residual < 10).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // 2. Reward "Perfect Fit" for next_item_size: If the current placement makes the bin 
    // exactly the size of the next item, we prioritize it strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // 3. New Bin Logic: If this is an empty bin, penalize it relative to the average 
    // fullness of other bins to prevent opening new bins when current ones are efficient.
    if bin_residual == bin_capacity {
        // We only open a new bin if the average residual is already quite low (bins are full).
        score += 40.0 + (mean_residual * 0.5);
    }

    // 4. Scarcity adjustment: If this is the last chance to fit the item in an existing bin,
    // lower the score to prioritize closing the item into an existing bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression damping: As we approach the end of the stream, prioritize 
    // packing density over lookahead.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Core objective: Best-Fit Decreasing (BFD) logic via post_residual.
    // We penalize high residuals to keep bins packed tightly.
    let mut score = post * post;

    // Lookahead logic: If a future item is known, penalize bins that leave 
    // too little space to accommodate the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Severe penalty for creating 'orphaned' space that cannot fit the next item
            score += 1000.0 * (next_item_size as f64 - post as f64);
        }
    }

    // Dynamic density adjustment: As the stream progresses, prioritize closing bins
    // to minimize the number of open bins (Active Bin Packing).
    // We penalize keeping too many bins open as we near the end of the stream.
    score += (open_bins_count as f64) * progress * 50.0;

    // New-bin thresholding:
    // If this is an empty bin (bin_residual == bin_capacity), calculate the cost of 
    // opening it vs using existing ones. We add a significant premium to opening
    // a new bin that decreases as we get closer to the end of the stream (to clear remaining items).
    if bin_residual == bin_capacity {
        score += 250.0 * (1.0 - (progress * 0.5));
    }

    // Interaction with mean_residual:
    // Penalize bins that deviate significantly from the mean to promote uniform fill levels.
    let deviation = (post as f64 - mean_residual).abs();
    score += deviation * 2.0;

    // Final normalization: If fitting_bins_count is 1, this is the only bin that can
    // accommodate the item. We reduce the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it creates "fragmentation" 
    // that is likely unusable given the constraint (item_size >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Integration: If the next item cannot fit into the current post_residual,
    // we penalize this placement to keep the bin open for a better fit later.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Global Bin Pressure: As the stream progresses, favor packing tighter to 
    // prevent a linear increase in open bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 4. New Bin Thresholding: If this is a new bin (residual == capacity), 
    // only choose it if the penalty for existing bins is higher than this baseline.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is scaled by current fragmentation.
        score = 35.0 + (mean_residual * 0.5);
    } else {
        // 5. Fit Efficiency: Penalize bins that are becoming too empty relative to others.
        if (post_residual as f64) > mean_residual {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small gaps (1-9) 
    // that are too small for most incoming items, while balancing the number of open bins.

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: 
    // Small residuals (1-9) are "dead zones" that are hard to fill. 
    // If post_residual is in this range, we inflate the cost to discourage it.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64).sqrt();
    }

    // 2. Open Bin Pressure: 
    // If we have many open bins, we should prioritize filling them to avoid new bin overhead.
    // If we have very few, we can be more selective.
    score += (open_bins_count as f64) * 0.5;

    // 3. Lookahead Integration:
    // If a future item exists, prioritize bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Bonus for "dual-fit" potential
        } else if post_residual > 0 {
            score += 10.0; // Penalty if this placement blocks the next item
        }
    }

    // 4. New Bin Logic:
    // When evaluating a brand-new bin (bin_residual == bin_capacity), 
    // the score must be high enough that we only open it if existing bins are terrible.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is constant, but scales with global utilization
        // represented by mean_residual. Lower mean_residual means bins are full; 
        // high mean_residual means we have plenty of space elsewhere.
        score = 45.0 + (mean_residual * 0.2);
    }

    // 5. Criticality:
    // If this is the only bin that fits, we should take it even if the fit is suboptimal.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
    // We prioritize Best-Fit behavior (smallest post_residual) 
    // but penalize creating "dead space" that cannot fit typical items.

    let mut score = post_residual as f64;

    // 1. Penalty for creating very small, unusable remainders (fragmentation)
    // If post_residual is < 10, it's likely "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead optimization: If a next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect fit" for the upcoming item
            score -= (100.0 - (post_residual as f64 - next_item_size as f64)) * 0.2;
        } else {
            // Penalize bins that would force a new bin for the next item
            score += 15.0;
        }
    }

    // 3. Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If we have few, be more conservative about packing density.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += (open_bins_count as f64 * 0.5) * (1.0 - fill_ratio);

    // 4. Threshold for New Bin: Only open a new bin if the current fit is extremely poor
    // (i.e., post_residual is large).
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Only pick this if the average residual of existing bins is already very tight,
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score = 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    // 5. If this bin is the only one that fits, give it a significant priority boost.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space: we prefer smaller residuals (Best Fit behavior).
    let mut score = post_res;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == capacity), add a dynamic penalty
    // that increases as the stream progresses to force tighter packing later.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 40.0);
    }

    // Lookahead coupling:
    // If we have a next item, penalize placements that create a residual too small
    // to accommodate the next item. This is a non-linear "soft-threshold".
    if next_item_size > 0 {
        let gap_deficit = (next_item_size as f64 - post_res).max(0.0);
        // Apply a quadratic penalty for "wasting" space that could have held the next item.
        score += (gap_deficit * gap_deficit) / 10.0;
    }

    // Multi-bin pressure:
    // If many bins are open, we want to consolidate. Increase score if we pick 
    // a bin that is already "mostly empty" (high mean_residual) to favor
    // filling up bins that are already partially full.
    if open_bins_count > 1 {
        score += (mean_residual - post_res) * (open_bins_count as f64 / 10.0);
    }

    // Criticality adjustment:
    // If this is the only bin that can fit the item, reward it to prevent
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that cannot fit future items.
    // If post_residual is small but > 0, it's often worse than leaving it 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If we have a next_item, we want the current post_residual to accommodate it perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item precisely.
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Penalize if current placement forces a new bin for the next item.
            score += 40.0;
        }
    }

    // 3. Balance against mean_residual to prevent fragmentation.
    // If this bin's residual is significantly lower than the mean, it's a "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Force Best-Fit logic:
    // If fitting_bins_count is low, we are running out of options. 
    // Prioritize finishing off bins that are already nearly full.
    if fitting_bins_count <= 2 {
        score -= (100.0 - bin_residual as f64) * 0.2;
    }

    // 5. New bin penalty:
    // If bin_residual == bin_capacity, we are considering a new bin.
    // Make it expensive unless all existing bins are bad fits.
    if bin_residual == bin_capacity {
        score += 65.0 - (open_bins_count as f64 * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We target residuals that leave space for common item sizes (harmonic-like thresholds).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Adaptive pressure: If many bins are open, be more aggressive at filling them tightly.
    // If we are at the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless
    // the fitting_bins_count is low or the current item is large.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 60.0;

        // If we are forced to open a new bin because no fit is good, reduce penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }

        // If the item is very large, opening a new bin is better than polluting a tight bin.
        if item_size > 70 {
            score -= 15.0;
        }
    } else {
        // Reward bins that are becoming "fuller" (harmonic alignment).
        // Bins with residuals closer to the mean are generally healthier.
        let residual_diff = (post_residual as f64 - mean_residual).abs();
        score += residual_diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward Best-Fit behavior: prefer smaller post_residuals (tighter packing)
    // 2. Penalty for creating unusable space: if post_residual < 10 (the minimum item size),
    //    it becomes 'dead space'. We penalize this heavily unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead logic (harmonic coupling):
    // If next_item_size is known, favor bins that can accommodate it later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: this bin can take the next item too.
            score -= 25.0;
        } else {
            // Penalty: this bin won't fit the next item, forcing a new bin or another search.
            score += 10.0;
        }
    }

    // 4. Global state pressure:
    // If we have many open bins, we should be more aggressive about filling them
    // to avoid creating fragmented capacity.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 2.5 * (1.0 - progress);

    // 5. New Bin logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current options are very poor (high score).
    if bin_residual == bin_capacity {
        // Only open new if we have no good fits (fitting_bins_count is low)
        // or if the average residual is already quite low (suggesting we are stuck).
        if fitting_bins_count > 0 {
            score += 40.0; // Heavily penalize opening a new bin if an existing one works
        } else {
            score -= 10.0; // Otherwise, accept the new bin
        }
    }

    // 6. Harmonic refinement:
    // Favor bins that align with common item fractions to leave room for future items.
    let residual_mod = (post_residual % 20) as f64;
    score += residual_mod * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit logic: penalize large post_residuals (dead space).
    // We favor bins where the remaining space is small, but not so small that
    // it becomes unusable for future items (e.g., < 10).
    if post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization (k=2):
    // If the next item fits into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic/Modulo pressure:
    // Avoid leaving residuals that are mathematically awkward for common item sizes.
    // Penalize residuals that are prime or near capacity thresholds.
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // 4. Global state awareness:
    // If we have many open bins, prioritize filling existing bins (Best Fit).
    // If we have very few, be more conservative about keeping space for large future items.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += (open_bins_count as f64) * 2.0 * fill_ratio;

    // 5. Threshold for opening a new bin:
    // If the bin is brand new (residual == capacity), apply a high penalty to force
    // usage of existing bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If there are other bins that could fit the item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 6. Final progression smoothing:
    // As we approach the end of the stream, prioritize packing tightly regardless of future potential.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score: prefer tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space that is too small for common items
    // If post_residual is small but > 0, it's often a "dead zone". 
    // We penalize values below 10 (as minimum item size is 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize keeping larger bins open
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual < next_item_size {
            // If this placement prevents the next item from fitting, penalize heavily
            40.0 * (1.0 - progress)
        } else {
            // If this placement is synergistic with the next item, reward it
            -15.0 * (next_item_size as f64 / bin_capacity as f64)
        };
        score += next_fit_penalty;
    }

    // Global state awareness: 
    // If fitting_bins_count is 1, this is the last chance. 
    // Avoid opening a new bin unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        // This is a "New Bin" call
        if fitting_bins_count > 0 {
            // Only open if current bins are very full (mean_residual is low)
            score += 60.0 * (mean_residual / bin_capacity as f64);
        } else {
            // No other choice
            score -= 100.0;
        }
    } else {
        // Existing bin logic
        // If we have many open bins, encourage consolidation
        score += (open_bins_count as f64 * 0.5);

        // Dynamic thresholding: as we near the end of the stream, be less picky
        score -= (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let capacity = bin_capacity as f64;

    // Base score is the post_residual (Best Fit principle).
    // Penalize smaller residuals to prioritize tighter packing.
    let mut score = post;

    // If this is a new bin, apply a progress-dependent penalty.
    // Early in the stream, we are more aggressive at packing into existing bins.
    // Late in the stream, we are more willing to open new bins to clean up remaining space.
    if bin_residual == bin_capacity {
        score = (capacity * 0.75) + (progress * capacity * 0.4);
    } else {
        // Non-linear coupling: penalize bins that leave behind "dead space" that
        // is too small for the next item or the average item size.
        // We calculate a "waste" penalty based on the post_residual.
        let waste_penalty = if next_item_size > 0 {
            if post < next_item_size as f64 {
                (next_item_size as f64 - post).powi(2) * 0.5
            } else {
                0.0
            }
        } else {
            0.0
        };

        // Encourage filling bins that are already "half-full" or more to 
        // minimize the total number of active bins.
        let usage_factor = (capacity - bin_residual as f64) / capacity;
        let density_reward = -15.0 * usage_factor * (1.0 - progress);

        score += waste_penalty + density_reward;

        // If this is the last fitting bin, give it a slight preference to avoid 
        // opening a new bin prematurely.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic).
