    // 2. Lookahead Synergy: If post_residual can accommodate the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        // High reward for perfect fits or near-perfect fits for the next item.
        let synergy = (post_residual - next_item_size) as f64;
        score -= (100.0 - synergy) * 2.5;
    }

    // 3. Fragmentation Control: Penalize bins that deviate significantly from the mean residual
    // to keep the "fill level" consistent across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.8;

    // 4. Scarcity/Efficiency: If this is the only bin that can fit the item, prioritize it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. New Bin Thresholding: Discourage opening a new bin unless the current fit is terrible.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are all very crowded 
        // (mean_residual is low) or if we are early in the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 - (mean_residual * 0.5) + (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Lookahead: If next_item_size is large, favor bins that can accommodate it.
    //    If post_residual < next_item_size, we penalize the bin because it creates stranded space.
    if !is_new_bin && next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // 3. Dynamic Thresholding: As the stream progresses, become more aggressive 
    //    at keeping bins tight.
    if !is_new_bin {
        let tightness_penalty = (post_residual as f64 - mean_residual).powi(2) * (1.0 - progress);
        score += tightness_penalty;
    }

    // 4. New Bin Decisioning:
    //    If we are early in the stream, be conservative about opening new bins.
    //    If we are late, allow new bins if current fitting options are suboptimal.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalty for opening a new bin is higher when we have many open bins 
            // that are nearly empty (low mean_residual).
            let base_new_bin_cost = 40.0;
            score = base_new_bin_cost + (mean_residual * 0.5) - (progress * 10.0);
        }
    } else {
        // Favor bins that have become "nearly full" (Best-Fit Decreasing intuition)
        // Subtract to reward bins that are already tight.
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Critical Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // We weight this by the total residual space to avoid creating many partially empty bins.
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead matching: If the post_residual can fit the next item, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward is proportional to how snugly the next item would fit.
        score -= (100.0 - (post_residual - next_item_size) as f64) * 2.5;
    }

    // 3. Last-Chance Logic: If this is the only bin that can fit the current item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // 4. Empty Bin Threshold: Make opening a new bin expensive unless the current 
    // alternatives are extremely poor (i.e., they result in very awkward residuals).
    if bin_residual == bin_capacity {
        score += 85.0; 
        // If we are near the end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 50.0;
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the mean 
    // residual of currently open bins to promote uniform bin usage.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers" (very small unusable gaps)
    // We penalize post_residuals that are too small to fit common items (e.g., < 10)
    if post_res > 0.0 && post_res < 10.0 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to preserve capacity for the upcoming item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 15.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Dynamic adjustment based on stream progress. 
    // As we near the end of the stream, we become more aggressive in packing
    // tightly to avoid opening new bins.
    let tightness_factor = 50.0 * (1.0 - progress);
    score += (mean_residual - post_res) * tightness_factor;

    // Favor bins that are already open (penalty for opening new bins)
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low, 
        // or if the average residual of existing bins is already very poor.
        let open_penalty = 25.0 + (open_bins_count as f64 * 0.5);
        score += open_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residual (Best Fit logic)
    let mut score = post;

    // Penalize the new bin if we have fitting alternatives
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals
    if next_item_size > 0 {
        let gap_penalty = if post < next_item_size as f64 {
            // High penalty if we create a gap that cannot fit the next item
            (next_item_size as f64 - post).powi(2) * 0.5
        } else {
            // Reward if we leave just enough space for the next item
            -(post - next_item_size as f64).abs().powf(0.5) * 5.0
        };
        score += gap_penalty;
    }

    // Balance the global residual: avoid creating too many bins that have very low residuals early on
    // which leads to fragmentation later.
    let residual_balance = (post - mean_residual).powi(2) * (1.0 - progress);
    score += residual_balance;

    // Scale penalty for using too many bins as the stream nears completion
    if open_bins_count > 0 {
        score += (open_bins_count as f64 * progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Harmonic/Residual-Efficiency with lookahead coupling.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space that cannot accommodate typical items.
    // If post_residual is small but > 0, it is often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic scaling: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25).
    // This creates "clean" bins for future packing.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 20) as f64 * 1.5;
        score += harmonic_penalty;
    }

    // 3. Lookahead integration:
    // If we have a next_item, prioritize bins where post_residual is >= next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: bin can take the next item.
            score -= 40.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Risky: bin will likely not take the next item.
            score += 20.0;
        }
    }

    // 4. Global state awareness:
    // If this is the last chance to fit the item in an existing bin, favor it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. New bin penalty:
    // Discourage opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Dynamically increase new bin cost as the stream progresses to consolidate.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Mean residual bias:
    // Prefer bins that keep the overall average residual high to maintain flexibility.
    score += (mean_residual - post_residual as f64) * 0.5;

    score
}

