    // 2. Best-Fit logic: prioritize bins where the post_residual is small.
    // This is already partially captured by the base score, but we refine it.
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead logic: If post_residual is close to next_item_size, we reward this bin.
    // This creates a "perfect fit" expectation for the next step.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward placements that leave a residual capable of fitting the next item.
        if post_residual >= next_item_size {
            score -= (15.0 - (diff * 0.2));
        } else {
            // Penalize creating a "stranded" bin that is too small for the next item.
            score += 10.0;
        }
    }

    // 4. Global state awareness:
    // If we have many open bins, penalize opening a new one further.
    // If we have very few open bins, we can be more flexible.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Mean residual balancing:
    // Avoid creating bins that deviate significantly from the current average fragmentation.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Urgency:
    // If this is the only fitting bin, lower its score to ensure we don't open a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Penalty for opening a new bin: proportional to how many bins are already open 
        // and how much capacity we are "wasting" by ignoring existing fit options.
        score = (bin_capacity - item_size) as f64;
        score += (open_bins_count as f64) * 5.0;
        score += (fitting_bins_count as f64) * 20.0;
    } else {
        // Reward tight fits that leave little room for fragmentation
        // Use post_residual squared to heavily penalize "middling" gaps
        score = (post_residual * post_residual) as f64;

        // Lookahead heuristic: If the next item fits into the current post_residual,
        // we reward this bin placement to avoid fragmentation.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 2.5;
        }

        // Global state adjustment: If we are deep into the stream, prioritize 
        // filling bins tightly to minimize the count of open bins.
        if post_residual < 10 {
            score -= 15.0 * (1.0 - progress);
        }

        // Penalize bins that deviate significantly from the mean residual of all open bins
        // to encourage a uniform "fill level" across the working set.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // Critical threshold: if this is the only bin that can fit the item, 
        // prioritize it strongly to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

