    // We want to minimize post_residual, but prioritize filling bins tightly.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // As the stream progresses, we become more conservative about opening new bins.
    if is_new_bin {
        // New bin penalty increases with progress to force consolidation.
        score += 40.0 * (1.0 + progress);

        // If there's only one bin that can fit the item, opening a new one is almost always bad.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward placing in a bin that makes the residual close to the next item size
        // This is a non-linear lookahead coupling.
        if next_item_size > 0 {
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 15.0 * (1.0 - (diff / bin_capacity as f64));
        }

        // Penalty for creating "orphaned" space (very small residuals that are hard to fill)
        // If post_residual is < 10, it's often wasted unless it hits 0.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0 * (1.0 - progress);
        }

        // Interaction with mean_residual: favor bins that are already "tight" 
        // to keep the variance of residuals low.
        score += 0.5 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Target: Best-Fit Decreasing (BFD) logic with lookahead penalty/reward.
    // We want to minimize the post_residual (Best Fit), but penalize placements that
    // create "dead" space that cannot accommodate common future items (lookahead).

    let mut score = post_residual as f64;

    // 1. Reward bins that are almost perfectly filled (Best Fit principle)
    // We penalize larger post_residuals significantly.
    score += (post_residual as f64).powf(1.1);

    // 2. Penalty for creating "orphan" space that cannot fit typical items.
    // If post_residual is small but > 0, it often becomes unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 4. Harmonic/Fractional Logic: Penalize bins that leave space that is 
    // mathematically awkward (e.g., leaving 50-60 space is often better than 10-20).
    // This biases against leaving "fragmented" space.
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.5;
    }

    // 5. New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), set a high base cost.
    // Only pick if fitting_bins_count is low or current open bins have very poor residuals.
    if bin_residual == bin_capacity {
        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If it's an existing bin, reduce score if it's the only fitting bin
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // 6. Global density awareness
    // As the stream progresses, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": gaps smaller than the minimum likely item size (10)
    // are extremely hard to fill, so we treat them as high-cost.
    if post_residual > 0 && post_residual < 10 {
