    // Pressure balancing: if we have very few fitting bins, we are constrained.
    // If fitting_bins_count is 1, we are at a "critical" junction.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Incorporate global bin state: if the current bin's residual is significantly 
    // worse than the mean, penalize it to encourage consolidating items into "tighter" bins.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
