    // If the post_residual is small (e.g., < 10), it often becomes "dead space" 
    // that cannot fit most items (10-80 range). Penalize these "slivers".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Global Efficiency:
    // As the stream progresses, prioritize closing bins that are close to the mean_residual
    // to keep the active bin set compact.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.1 * progress;

    score
}

