    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 3. Open Bin Pressure: Penalize opening new bins when many are already active.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Lookahead Synergy: If we know the next item, reward bins that leave enough space
    // to accommodate the next item (if it fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.5;
    }

    // 5. Fitting Scarcity: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Global Efficiency: If our mean residual is high, we are being too wasteful.
    // Penalize high-residual bins more aggressively as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
