    // that favor packing items of similar sizes together.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (1..10) which is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic alignment: favor residues that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" for specific item classes.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead logic: if next_item_size fits in post_residual, drastically reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further encourage tight coupling if the next item is large
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // 4. If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we should prioritize using it, but only if the residual isn't catastrophically small.
    if fitting_bins_count == 1 && post_residual < 5 {
        score += 30.0; // Discourage packing into an only-fit bin if it leaves unusable space
    }

    // 5. Global state normalization: if we have many bins open, be more aggressive about filling
    // existing ones to prevent proliferation.
    let fill_pressure = (open_bins_count as f64) / (1.0 + (step_index as f64 / total_items as f64));
    score += fill_pressure * 2.0;

    // 6. New bin penalty: If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if existing ones are poor fits (high residual).
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin, adjusted by current distribution state
        score += 65.0 - (mean_residual * 0.3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "sliver" residuals that are 
