    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // 5. Progression scaling: As the stream nears the end, prioritize closing bins
    // by preferring smaller post_residuals (Best Fit).
    let progress = step_index as f64 / total_items as f64;
