        }
    }

    // Global state awareness:
    // If we are late in the stream, be more aggressive about filling existing bins
    // to avoid leaving fragmented space at the end.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // New bin logic:
    // Only open a new bin if the current fit quality is very poor (high post_residual)
