    // As progress increases, become more aggressive about filling bins (Best-Fit approach).
    // If post_residual is 0, we found a perfect fit, which is optimal.
    let mut score = post_res.powf(1.5 + progress);

    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless no existing bins can fit the item or we are late in the stream.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin prematurely
            score += 150.0 * (1.0 - progress);
        } else {
            // No choice but to open a new bin
            score = 0.0;
        }
    } else {
        // Favor bins that result in a post_residual that matches the next_item_size 
        // (Lookahead heuristic: try to prepare the bin for the next item).
        if next_item_size > 0 {
            let diff = (post_res - next_item_size as f64).abs();
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        }

        // Penalize bins that deviate significantly from the mean residual of other bins
        // to keep bin fill-levels balanced.
        let dev = (post_res - mean_residual).abs();
        score += 0.5 * dev;
    }

    score
}

