    }

    // Interaction term: If this bin's post-residual is significantly larger than the 
    // mean_residual of other bins, it's a "loose" bin. We penalize this variance 
    // to encourage tighter packing across the whole set.
    if post > mean_residual {
        score += (post - mean_residual) * 0.8;
    }

    // If this is the only bin that can fit the item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
