}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score: punish large post_residuals (Best Fit logic)
    let mut score = post;

    // Penalty for creating a 'dead zone' (residual space too small for any likely future item)
    // We assume items are generally > 10, so residuals < 10 are highly inefficient.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead coupling: If the next item could fit into this post_residual, 
    // reward this bin heavily (Best Fit + Lookahead).
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding based on stream progress:
    // Late in the stream, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // New bin penalty increases as the stream progresses to discourage fragmentation
        score += 40.0 + (progress * 30.0);
    } else {
        // Reward bins that have residuals closer to the mean_residual to keep bin filling uniform
        let deviation = (residual - mean_residual).abs();
        score += deviation * 0.2;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid wasting space
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize high open_bins_count to encourage packing items into existing infrastructure
    score += (open_bins_count as f64).powf(1.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

