    }

    // 3. Fitting Scarcity: If this is the only bin that can fit the current item,
    // we must prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 4. New Bin Thresholding: If considering a new bin, penalize based on 
