        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 3. Lookahead Integration: If the next item is large, favor bins that leave enough room for it.
    // If the next_item_size is large (e.g., > 60), penalize bins that will have little room left.
    if next_item_size > 60 && post_residual < next_item_size {
        score += 30.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 5. Global Efficiency: If current bin is very empty compared to the mean, prioritize it to consolidate space.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If the item fits perfectly, prioritize this bin heavily.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2. Lookahead compatibility: If the remaining space can fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 150.0;
        // Further reward if it leaves very little waste after the next item.
        let waste_after_next = post_residual - next_item_size;
        score -= (100.0 - waste_after_next as f64) * 0.5;
    }

    // 3. Penalty for "New Bin" creation: Only open a new bin if the best existing bin has a poor fit.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Apply a significant penalty to opening a new bin unless existing options are terrible.
            score += 120.0;
            // Scale penalty based on how full the average open bin is.
            score += (100.0 - mean_residual) * 0.8;
        }
    }

    // 4. Avoid creating small, unusable gaps (1..9 range is typically dead space for 10+ items).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 5. Dynamic balancing: If we are near the end of the stream, prioritize packing existing bins
    // to avoid leaving items stranded.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // 6. Last chance heuristic: If this is the only bin that can fit, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily, but scale down as the stream progresses
        // to prevent being trapped with many half-full bins at the end.
        score = 85.0 + (progress * 20.0);
    } else {
        // Best-Fit Decreasing logic: Favor bins that leave the least space (lower post_residual).
        // Penalty for creating 'dead space' that cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 40.0;
        }

        // Reward bins that bring the bin residual closer to the global mean,
        // promoting uniform bin usage and preventing fragmented bin states.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;

        // If this is the only bin that can fit the item, prioritize it to avoid
        // forcing a new bin allocation unnecessarily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Adaptive threshold: as we approach the end of the stream,
        // prioritize filling existing bins even if the fit is suboptimal.
        score -= (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Progress factor normalized [0, 1]
    let progress = step_index as f64 / total_items as f64;

    // Core penalty: post_residual (smaller is better, but 0 is perfect/tight fit)
    let mut score = post_residual as f64;

    // Favor tight packing: exponential penalty for large remaining space (waste)
    // We penalize the post_residual more heavily as we approach the end of the stream
    score += (post_residual as f64).powf(1.5) * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the stream progresses (to allow opening bins when space is tight)
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is 50.0, tapering off as we near completion
        score += 50.0 * (1.0 - progress);
    }

    // Lookahead: if the next item is large, penalize bins that leave too little space
    // to accommodate it, unless it's a perfect fit (post_residual == 0)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.2;
    }

    // Discourage fragmentation: penalize if this bin's residual deviates significantly from the mean
    // This pushes the algorithm toward a uniform filling level
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // If this is the only bin that can fit the current item, reward it to prevent
    // unnecessary new bin creation (unless the post_residual is extremely poor)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
