        let progress = step_index as f64 / total_items as f64;
        score -= progress * 30.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that are significantly below the current mean_residual,
    // as these are likely to become stranded.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

