    // 4. Global capacity optimization: Avoid creating bins with high residuals 
    // if the mean residual of existing bins is already high (clustering).
    if (post_residual as f64) > mean_residual && open_bins_count > 2 {
        score += 5.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // be more aggressive about filling smaller gaps to minimize terminal bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

