    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        // Reward bins that leave exactly enough space for the next item
        score -= (100.0 - fit_gap * 2.0);
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the current fit is terrible.
    // If this is a new bin (bin_residual == bin_capacity), apply a high base penalty.
    if bin_residual == bin_capacity {
        score += 45.0; 
