        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Global Packing Efficiency: If the current post_residual is significantly 
    // higher than the average, this is a "wasteful" bin. Penalize it.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the current item, 
    // reduce its score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
