    }

    // 2. Lookahead logic: If the next item is large, prioritize keeping the residual 
    // high enough to accommodate it, or force a new bin if this bin will be too restricted.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize placing the current item here if it blocks the next item from fitting.
            score += 25.0;
        } else {
            // Reward placing the current item here if it leaves exactly enough room for the next.
            if (post_residual as i32 - next_item_size as i32).abs() < 5 {
                score -= 15.0;
            }
        }
    }

    // 3. Global State: Use mean_residual to avoid fragmented bins.
    // If this bin's post_residual is significantly lower than the global average, 
    // it's a good "tight" bin.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Scarcity/Progression: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 5. New Bin Logic: If bin_residual == bin_capacity, it's a new bin.
    // Only open a new bin if the current best existing bin is extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalty for opening a new bin if we can fit the item in an existing one.
            score += 40.0;
        } else {
            // No other option, force selection.
            score -= 20.0;
        }
    }

    score
