pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals that are likely to become stranded (1-9 range)
    // as the stream progresses, we become more conservative about creating small gaps.
    let stranding_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Reward bins that keep the post_residual close to the mean_residual of other bins
    // to encourage bin homogenization.
    let homogeneity_bonus = (post - mean_residual).abs() * 0.5;

    // If this is the last chance to fit an item, penalize opening a new bin heavily
    // unless the fit is extremely poor.
    let last_chance_penalty = if fitting_bins_count == 1 && bin_residual == bin_capacity {
        50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Lookahead: If next item is large, favor bins that leave enough room for it.
    let lookahead_alignment = if next_item_size > 0 {
        if post >= next_item_size as f64 {
            -10.0 * (next_item_size as f64 / 100.0)
        } else {
            15.0 * (next_item_size as f64 / 100.0)
        }
    } else {
        0.0
    };

    // Base score: prioritize smaller post_residuals (Best Fit logic)
    // weighted by non-linear interaction with stream progress.
    let base_score = post * (1.0 + progress * 0.2);

    base_score + stranding_penalty + homogeneity_bonus + last_chance_penalty + lookahead_alignment
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the basic Best-Fit objective (minimizing post_residual)
    let mut score = post_residual as f64;

