    // We penalize remainders in the (0, 10) range heavily as they are unlikely to accommodate future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64);
    }

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin
    // This effectively implements a "Next-Fit-Decreasing" lookahead synergy
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // New-bin thresholding: Discourage opening a new bin unless the existing bins are poor fits
    // We add a cost to the new bin (bin_residual == bin_capacity) to force usage of existing space
    if bin_residual == bin_capacity {
        score += 12.0;

        // If we have many open bins already, make opening a new one even more expensive
        score += (open_bins_count as f64) * 0.5;
    }

    // Harmonic class adjustment: Favor bins that leave a residual which is a multiple of common item sizes
    // This increases the probability of fitting future items perfectly
    let harmonic_remainder = post_residual % 25;
    if harmonic_remainder == 0 {
        score -= 5.0;
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins (minimizing residuals)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.1;

    // Penalty for "Last Chance" bins: If only one bin fits, we are forced to pick it, 
    // but if it's a very poor fit, we might prefer opening a new one. 
    // We soften the score if this is the only bin that fits.
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
