    // proportional to the progress of the stream (as packing efficiency matters more late-game).
    if next_item_size > post_residual && next_item_size > 0 {
        score += (1.0 + progress) * 15.0;
    }

    // New bin management:
    // If this is a new bin (bin_residual == bin_capacity), we only want to pick it 
    // if the current fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // We set the threshold for opening a new bin to be quite high, 
        // effectively forcing the algorithm to use existing bins unless they 
        // would result in a very inefficient fit (> 25 remaining space).
        score += 25.0 + (progress * 20.0);
    } else {
        // If it's an existing bin, favor bins that are closer to the mean residual
        // to keep usage balanced, but weight this less than the primary Best-Fit.
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Scarcity adjustment:
    // If this is the only bin that can fit the item, prioritize it heavily
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo logic: Favor post_residuals that are multiples of common item sizes
    // Modulo 10, 20, 25 are strong candidates for fitting future items
    let harmonic_penalty = (post_residual % 10) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
