    // 4. Threshold Logic: Discourage creating "unusable" small gaps (1-9)
    // If we create a gap between 1 and 9, it is extremely difficult to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 5. Open Bin Management: If this is the only fitting bin, prioritize it to avoid new bin overhead
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // only pick it if the average residual is already very low (forcing a fresh start)
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            // Penalize new bin if existing bins have decent space
            score += 100.0;
        } else {
            // Otherwise, keep it neutral/slightly high to prefer existing bins
            score += 45.0;
        }
    }

    // 7. Progression scaling: As we approach the end of the stream, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
