    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Global State Efficiency: Penalize opening new bins if there are still 
    // fitting options, unless the current bin is very efficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin prematurely
            score += 100.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Reward for opening a new bin when forced
            score -= 10.0;
        }
    }

    // 3. Lookahead Synergy: If the current bin fits the next item perfectly (or nearly), 
    // prioritize this bin to preserve future capacity.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_gap) * 0.2;
    }

    // 4. Dynamic Time Horizon: As we approach the end of the stream, 
    // tighten the tolerance for small residuals to maximize packing density.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * progress;
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the 
    // global mean residual to keep bin states uniform.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
