        0.0
    };

    // Reward tighter packing (smaller post_residual)
    let tightness_score = post_residual as f64;

    // Open bin pressure: discourage opening too many bins early on.
    // If this is a new bin, apply a penalty that increases with open_bins_count.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64 * 2.5) + (1.0 - progress) * 15.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, avoid leaving a residual
    // that is just slightly smaller than that next item.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        (next_item_size - post_residual) as f64 * 0.8
    } else {
        0.0
    };

    // If this is the last chance to fit the item in an existing bin,
    // strongly favor fitting it rather than opening a new one.
    let desperation_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    tightness_score + dead_space_penalty + new_bin_penalty + lookahead_penalty + desperation_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive Lookahead: Reward placing items such that the next item fits perfectly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the remaining space is almost exactly the next item
            let waste = post_residual - next_item_size;
            score -= (100.0 - waste as f64) * 0.5;
        } else {
            // Penalty if we create a residual that cannot accommodate the next item
            score += 20.0;
        }
    }

    // 3. Balance usage across bins: Avoid creating outliers from the mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 4. Threshold management: If this is the last fitting bin, prioritize it to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin logic: Only open a new bin if the current fit is extremely inefficient
    if bin_residual == bin_capacity {
        // High cost to open a new bin; only accept if the average residual is already high
        score = 60.0 + (mean_residual * 0.5);
    }

    // 6. Progressive tightening: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (wasteful residual)
    // We prioritize bins that leave very little space (Best Fit)
    // But we penalize small residuals that are too small to fit common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
