        } else {
            score += 10.0; // Penalize bins that cannot fit the next item
        }
    }

    // Global state optimization: 
    // If we are at the end of the stream, prioritize filling existing bins aggressively
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Handling the "New Bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already quite low (highly packed)
        // or if we have very few bins open.
        let dynamic_threshold = 20.0 + (progress * 30.0);
        if mean_residual > dynamic_threshold && open_bins_count < 5 {
            score += 5.0; // Moderate penalty to discourage opening new bins too early
        } else {
            score += 45.0; // Heavy penalty to force usage of existing bins
        }
    }

    // Final adjustment based on how many bins can actually fit this item
    // If only one bin can fit it, we should be very careful not to waste it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) unless it is a perfect fit
    let fragmentation_penalty = if post == 0.0 { 0.0 } else { 1.0 / (post + 1.0).sqrt() };

    // Use lookahead to discourage opening new bins when a tight fit is possible
    let lookahead_pressure = if next_item_size > 0 {
        if post_residual < next_item_size { 15.0 } else { -5.0 }
    } else { 0.0 };

