    // to avoid leaving large gaps that cannot be filled later.
    let progress_weight = 20.0 * progress;

    // If this is the only bin that fits the item, reward it to prevent unnecessary new bin creation
    let scarcity_bonus = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // Base score: prioritize smaller post_residuals (Best Fit logic)
    // Add non-linear interaction between current residual and stream progress
    let mut score = post + (fragmentation_penalty * 10.0) + (progress_weight * (post / 100.0)) + lookahead_pressure + scarcity_bonus;

    // Special handling for new bin candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (wasteful) 
        // or if we are at the very end of the stream and have no other choice.
        score += 40.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
