        } else {
            // If no fitting bin, opening a new one is mandatory.
            score = 0.0;
        }
    } else {
        // If the bin is already open, reward bins that maintain a residual close to the mean.
        // This keeps packing density uniform.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
