            // or if we have very few fitting options.
            score += 45.0 - (mean_residual * 0.5);
        }
    }

    // 2. Lookahead matching: If the next item fits perfectly into this post_residual, 
    // reward this bin significantly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Reward bins that leave enough room for the next item
            score -= 10.0;
        } else {
            // Penalize if this placement makes the next item impossible to fit here
            score += 5.0;
        }
    }

    // 3. Pressure management: If this is the last fitting bin, prioritize it to avoid 
    // fragmenting space in other bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Tightness bias: Prefer bins that result in very small residuals (Perfect Fit)
    if post_residual == 0 {
        score -= 50.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize 
    // tighter packing to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
