pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // We add a penalty for "fragmentation" (small post_residual) 
    // that is non-linearly scaled by stream progress.
    let fragmentation_penalty = if post_res < 10.0 && post_res > 0.0 {
        (10.0 - post_res).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead logic: Reward bins that fit the next item specifically
    let next_item = next_item_size as f64;
    let lookahead_bonus = if next_item > 0.0 && post_res >= next_item {
        -(post_res - next_item).powf(0.5) * 5.0
    } else if next_item > 0.0 && post_res < next_item {
        // Penalty for making a bin unable to fit the next item
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Penalty for opening a new bin prematurely
    // If bin_residual == capacity, we are evaluating a new bin creation
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily discourage new bins if existing ones can fit the item
            30.0 * (1.0 + progress)
        } else {
