        }
    } else {
        0.0
    };

    // Balancing residual distribution:
    // Penalize deviating significantly from the mean residual of open bins
    let deviation_penalty = (post_res - mean_residual).abs() * 0.1;

    post_res + fragmentation_penalty + lookahead_bonus + new_bin_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
