        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    // Global state awareness: If we are late in the stream, favor filling existing bins aggressively.
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic threshold.
    // We only open a new bin if the best fit in existing bins is "very poor" (post_residual is large).
    if bin_residual == bin_capacity {
        // High penalty to prevent opening new bins unless necessary.
        score += 65.0;

        // If we have few fitting bins, opening a new one is slightly less penalized.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Reward bins that bring the residual closer to the mean_residual of other bins,
        // which helps keep the "bin landscape" uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Minimize remaining space (Best Fit)
    let mut score = post_res;

    // Penalty for leaving small, unusable gaps (1-9) that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If a future item is known, penalize bins that can't fit it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower residual)
    // to prevent fragmentation towards the end of the stream
    score += (progress * 40.0) * (post_res / bin_capacity as f64);

    // If this is the only bin that can fit the item, give it a significant discount
    // to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize new bin opening unless it's truly optimal
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    // Coupling with mean_residual to favor bins that are already "tight"
    // This helps maintain a uniform fill level across bins
    score += (post_res - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot fit common items)
    // We penalize residuals that are non-zero but smaller than the minimum likely item size (10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic lookahead: If next_item_size is known, favor bins that can accommodate the sum
    // of current and next. If next_item_size fits in post_residual, reduce score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Pressure management: If we are near the end of the stream, prioritize tight packing (Best Fit)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 4. Harmonic class thresholding: 
    // If the bin is new, penalize heavily unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Accept opening a new bin if it's the only option
        }
    }

    // 5. Global optimization: Bias against opening too many bins by penalizing high open_bins_count
    // relative to the mean_residual. If mean_residual is high, we have capacity; don't open new ones.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * (100.0 / (mean_residual + 1.0));
    }

    // 6. Modulo-based "perfect fit" incentive:
    // If post_residual is 0, we have an ideal packing.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with Dead Space Penalty.
    // 1. If bin is new, penalize based on open_bins_count to encourage consolidation.
    // 2. Penalize post_residual values that are likely to be "unusable" (e.g., < 10).
    // 3. Reward placements that leave post_residual close to the size of the next_item_size (lookahead).

    let mut score = post_residual as f64;

    // Penalty for creating a new bin: higher when we already have many bins open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.5);
    } else {
        // Dead space penalty: If remaining space is too small to fit the smallest likely item (10), 
        // penalize it heavily unless it closes the bin perfectly (0).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead bonus: If the post_residual is close to the next_item_size, we favor this bin.
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score += diff * 0.2;
        }

        // Pressure: If this is the only bin that fits the item (fitting_bins_count == 1),
        // we heavily prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Secondary pressure: If mean residual is high, we are being too loose; prioritize tighter fits.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in the smallest post_residual.
    // This is the baseline, already captured by score = post_residual.

    // 2. Penalty for opening a new bin if other bins are available.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // 3. Lookahead Matching: If we have a next_item, we want a post_residual 
    // that is either very close to 0 (perfect fit) or close to next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // Reward if post_residual can accommodate the next item
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (diff / bin_capacity as f64));
        } else {
            // Penalize if post_residual is small but unusable for next_item
            score += 10.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly 
    // from the average fullness, which helps keep space distributed evenly.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation;

    // 5. Critical Constraint: If this is the only bin that can fit the item, 
    // strongly incentivize choosing it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progress Scaling: As we reach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The remaining space after placing current item.
    // We aim for "Best Fit" logic (low post_residual) but modified by lookahead.

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (small residuals that are hard to fill).
    // If post_residual is small but > 0, it's often better to have it be 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // significantly reward this placement (Best Fit Decreasing logic).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 3. Global state: If we are nearing the end of the stream, prioritize 
    // closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have fitting bins available.
        // Penalty increases as we progress through the stream.
        score += 50.0 + (progress * 50.0);
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Balance: If the current bin's residual is significantly better than 
    // the mean residual of all open bins, reward it to consolidate space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. If this is the last chance for the current item to fit in an existing bin,
    // reduce the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize small post_residuals (fragmentation) more heavily as the stream progresses.
    let fragmentation_penalty = (1.0 / (post_res + 1.0)) * (1.0 + progress * 5.0);

    // Encourage filling bins that are already "below average" to keep high-residual bins open for larger future items.
    let mean_deviation = (bin_residual as f64 - mean_residual).abs();

    // Lookahead logic: if next item is large, favor bins that leave enough space for it.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_res) * 2.0
    } else {
        0.0
    };

    // Discourage opening new bins unless the current best fit is very poor.
    let new_bin_penalty = if bin_residual == bin_capacity {
        // Only open a new bin if the current progress is early or if there's no good fit.
        15.0 + (progress * 10.0) 
    } else {
        0.0
    };

    // Combine terms:
    // 1. Post-residual (minimize)
    // 2. Fragmentation (penalize)
    // 3. New bin penalty (penalize)
    // 4. Lookahead (penalize if next item won't fit)
    let score = post_res 
        + fragmentation_penalty 
        + new_bin_penalty 
        + lookahead_penalty 
        + (mean_deviation * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

