    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward it.
    // This acts as a "Harmonic lookahead" to prevent fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
    }

    // 3. Harmonic Class Logic: Reward residuals that align with common item sizes.
    // Small residuals (below 10) are often "trapped" space.
    if post_residual < 10 {
