        // Otherwise, penalize the new bin to force usage of existing ones.
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If it's an existing bin, reward it based on how much it helps reduce fragmentation.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
