    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity/Density management: 
    // If we have few fitting bins, we are forced to be pickier to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // Strongly prefer filling the last chance bin
    }

    // 5. Harmonic thresholding: penalize residuals that fall into "unusable" ranges (1-9)
    // as items are >= 10, any residual < 10 is effectively permanent waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 6. New Bin Logic:
    // Only open a new bin if the current "best" fit is extremely poor (large residual)
    // or if the stream is nearing the end and we want to consolidate.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high to favor packing existing bins
        score = 85.0; 

