        // Lookahead heuristic: If the next item can fit in the current post_residual,
        // prioritize bins that accommodate it better.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward bin that leaves room for the next item
            } else {
                score += 10.0; // Penalize bin that forces a new bin for the next item
            }
        }

        // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Balance residual space relative to the mean of all open bins
        // If our bin is much emptier than the mean, it's a "poor" fit, penalize it
        if (post_residual as f64) > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic
    // We prioritize bins that leave a post_residual which is a multiple of common small item sizes (e.g., 20, 25)
    // to minimize "stranded" space that cannot accommodate future items.

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in the "danger zone" (1..9), we heavily penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Modulo Alignment: Favor residuals that align with potential future item sizes (20, 25, 33).
    // These are common harmonic divisors of 100.
    let harmonic_alignment = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // 3. Lookahead Integration: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly fit the next item
            score -= 15.0;
        } else {
            // Penalize bins that will definitely force a new bin for the next item
            score += 10.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize opening a new one unless necessary.
    // fitting_bins_count == 0 implies a new bin is required.
    if fitting_bins_count == 0 {
        // This is a new bin candidate. Penalize it based on how many bins are already open.
        score += (open_bins_count as f64) * 2.5;
    } else {
        // If we are choosing between existing bins, prefer the one with the smallest residual (Best Fit)
        // but adjusted by how close the mean_residual is to the current bin_residual.
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    // 5. Progression Scaling: As we approach the end of the stream, be more conservative with space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'unusable' slivers (1-9 space left).
    // These gaps are too small for most items (min size 10), causing wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // Pressure: Penalize opening new bins when existing bins have capacity.
    // If we are looking at an empty bin (new bin candidate):
    if bin_residual == bin_capacity {
