        score -= (bin_capacity - post_residual) as f64 * 0.1;

        // Lookahead heuristic: If the next item fits into the current post_residual,
        // prioritize this bin to maximize packing density.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Penalize the use of a bin if it is the only one that can fit the item
    // but the item itself is small (prefer saving the 'tight' bin for a larger item).
    if fitting_bins_count == 1 && item_size < 30 {
        score += 10.0;
    }

    // Progression scaling: As we approach the end of the stream, prioritize
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
