pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Encourage Best-Fit behavior by penalizing large post_residuals
    // 2. If this is a new bin, apply a heavy penalty to keep it as a last resort
    if bin_residual == bin_capacity {
        score += 45.0; 
    }

    // 3. Lookahead Logic: If the next item fits perfectly in the remaining space, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward bins where the post-residual is nearly perfectly filled by the next item
        score -= (30.0 / (1.0 + diff));
    }

    // 4. Fragmentation avoidance: Penalize leaving a residual that is too small for any likely future item
    // If the residual is between 1 and 9 (very small), it's often "dead space"
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Global state normalization:
    // If we have many open bins, we are more aggressive about packing tightly.
    // If we have few bins, we are more tolerant of opening a new one to preserve space in existing bins.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // 6. Leverage fitting_bins_count:
    // If this is the only bin that can fit the item, prioritize it strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 7. Balance against the mean residual of the system to maintain uniform packing
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
