        score -= 5.0;
    }

    // 5. New Bin Penalty: If this is a new bin (bin_residual == bin_capacity), 
    //    apply a significant penalty unless it's the only option.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0;
        } else {
            // If no other bin fits, we must open a new one; keep score low.
            score -= 20.0;
        }
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    //    be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the "unusable" range (1-9),
    // heavily penalize it to force tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If the next item is large (e.g., > 50), 
    // prioritize leaving enough space in the current bin to potentially fit it later.
    if next_item_size > 50 {
