        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Best-Fit Bias: Encourage filling bins that are already closer to the mean 
    // residual to maintain uniformity across open bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
