    // 4. Mean Residual Balancing: Avoid creating bins that deviate significantly 
    // from the current average density, preventing "orphan" bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression Scaling: As we approach the end of the stream, 
