}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small residues that are hard to fill)
    // We penalize residues between 1 and 9 (the smallest item size is usually 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item exists, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalty for stranding the next item if it could have fit elsewhere
            score += 15.0;
        }
    }

    // 3. Global awareness: Penalize opening new bins when current bins have high capacity
    if bin_residual == bin_capacity {
        // If it's a new bin, increase score based on how many open bins are available
        score += (open_bins_count as f64) * 2.0;
        // If we still have plenty of open bins, discourage opening a new one
        if open_bins_count > 5 {
            score += 40.0;
        }
    }

    // 4. Dynamic time horizon: As we approach the end of the stream, prioritize packing
    // tightly to finish in fewer bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: strongly prefer tight fits
        score += (post_residual as f64) * 0.5;
    }

    // 5. Balance the mean residual: Avoid deviating too far from the average state
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 6. Last chance logic: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) as they are likely dead space
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        25.0 * (1.0 - (post_residual as f64 / 10.0))
    } else {
        0.0
    };

    // Lookahead logic: Reward bins that fit the next item if the current fit leaves little room
    let lookahead_bonus = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 * (1.0 - progress)
        } else {
            10.0 * progress
        }
    } else {
        0.0
    };

    // Dynamic threshold: As stream progresses, tighten the requirement for a "perfect" fit
    // to avoid early fragmentation.
    let tightness_factor = (post * post) / bin_capacity as f64;

    // Bias against opening new bins unless necessary (fitting_bins_count == 0)
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            40.0 + (20.0 * (1.0 - progress))
        } else {
            -10.0
        }
    } else {
        0.0
    };

    // Interaction between mean_residual and current fit
    let deviation_penalty = (post - mean_residual).abs() * 0.5;

    tightness_factor + dead_space_penalty + lookahead_bonus + new_bin_penalty + deviation_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items)
    // Residuals < 10 are often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is large, prioritize leaving space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: we can fit the next item here. Reward this.
            score -= 30.0;
        } else if post_residual > 0 {
            // Moderate: we are fragmenting space that might be needed for the next item.
            score += 15.0;
        }
    }

    // 3. Density Balancing: Try to keep residuals close to the mean to avoid extreme fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. New Bin Logic (bin_residual == bin_capacity):
    // Only open a new bin if the current fit is "too tight" (leaving very little space)
    // or if we have many bins open and should try to consolidate.
    if bin_residual == bin_capacity {
        // High penalty to prevent opening a new bin unless existing fits are poor.
        score += 45.0;
        // If we have many open bins, we are desperate; reduce the penalty.
        score -= (open_bins_count as f64).min(10.0) * 2.0;
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Modulo-based "Perfect Fit" reward:
    // If we fill the bin perfectly or near-perfectly, reward it.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
