pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" (under 20% utilization)
    if post_residual > 80 {
        score += 150.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize aggressive packing (tightest fit)
    // If early in the stream, prioritize keeping bins open that have higher mean residuals for future large items
    if progress > 0.8 {
        score += post_residual as f64 * 2.5;
    } else {
        score -= (mean_residual - post_residual as f64).abs() * 0.5;
    }

    // Lookahead logic: If the next item is large, avoid leaving a residual smaller than next_item_size
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Penalty for opening a new bin if other bins could fit the item
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin && fitting_bins_count > 0 {
        score += 60.0 + (fitting_bins_count as f64 * 5.0);
    }

    // Reward bins that bring us closer to a "perfect fit" (residual 0)
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Favor bins that are already open to consolidate space
    if !is_new_bin {
        score -= (open_bins_count as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for the next item (Lookahead).
    // If post_residual is smaller than the next item, we create "stranded" space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic thresholding: As the stream progresses, prioritize closing bins (lower mean_residual).
    // We penalize bins that deviate significantly from the mean_residual to encourage pack density.
    let deviation = (post - mean_residual).abs();
    score += deviation * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the number of available fitting bins decreases.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no options or if the current options are very poor.
        // We scale the cost of a new bin by the number of bins already open.
        score += 25.0 + (open_bins_count as f64 * 0.5) + (progress * 15.0);
    } else {
        // If the bin is already open, reward it if it's the last available fitting bin.
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Non-linear coupling: Exponentially penalize very small residuals (dead space) that cannot fit common items.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: prioritize creating "clean" residuals that fit common item sizes
    // We favor post_residuals that are multiples of 10 or 25 (common bin-packing divisors)
    let harmonic_penalty = if post_residual % 10 == 0 { -5.0 } else { 2.0 };
    score += harmonic_penalty;

    // 3. Lookahead integration: If the next item fits into the post_residual, drastically reduce score
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
        // Reward creating an exact fit for the next item
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 4. Threshold handling: Avoid opening a new bin unless the current best fit is very poor
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate. 
        // Only choose this if the average residual of existing bins is already tight (mean_residual < 20)
        // or if no other bin can fit the item.
        if fitting_bins_count > 0 && mean_residual > 20.0 {
            score += 100.0; 
        } else {
            score += 40.0;
        }
    } else {
        // 5. Penalize bins that become "fragmented" (very small residual)
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // 6. Progressive scaling: As we approach the end of the stream, prioritize space density
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: 
    // If post_residual is small (1..9), it often creates "orphaned" space 
    // that cannot fit most items (since items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead synergy:
    // If we have a next item, prefer bins where the post_residual can fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    }

    // 3. Open bin pressure:
    // Penalize opening new bins if we have many bins already active, 
    // unless the current fit is excellent (post_residual is small).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 2.5;
    } else {
        // Reward bins that have residuals close to the mean to consolidate space.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 4. Scarcity handling:
    // If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // 5. Final adjustment for packing density:
    // Lower post_residual is always better, but we scale it to ensure 
    // it competes with the penalty logic.
    score += (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize creating very small gaps that are hard to fill (less than 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if it creates a perfect fit for the next item.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. New Bin Thresholding: Penalize opening a new bin unless the current fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider new bin if we have very few fitting options or the average waste is already high.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
        // As the stream progresses, discourage new bins more aggressively.
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 4. Mean Residual Balancing: Favor bins that keep the overall average residual lower.
    // If this bin's post-fit residual is better than the current mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Dynamic weight that increases as we approach the end of the stream.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    } else {
        // Reward for keeping the residual small (Best Fit).
        // If it's a perfect fit, prioritize heavily.
        if post_residual == 0 {
            score -= 10.0;
        }

        // Lookahead heuristic: If the next item fits into the current post_residual, 
        // prioritize this bin to preserve bin capacity.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Global state awareness: 
        // If this is the only bin that fits the item, avoid it if the post_residual is too small
        // (creating "dead space" that likely cannot hold future items).
        if fitting_bins_count == 1 && post_residual < 10 {
            score += 20.0;
        }

        // Balance residual distribution: 
        // Penalize bins that deviate significantly from the mean_residual
        // to encourage uniform fill levels.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit principle).
    let mut score = post;

    // Penalty for creating 'fragmented' space (small residuals that are hard to fill later).
    // If post_residual is in the range (0, 10), it is very likely to become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Lookahead influence: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 * (1.0 - (next_item_size as f64 / post_residual as f64));
    }

    // Dynamics: As we approach the end of the stream, prioritize closing bins 
    // (lowering the residual) to avoid leaving many partially filled bins.
    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with how many existing bins could have accepted the item.
    // We only open a new bin if the "best fit" in an existing bin is catastrophically bad.
    if bin_residual == bin_capacity {
        score += 35.0 + (fitting_bins_count as f64 * 15.0);
    }

    // Interaction with global state: penalize opening new bins if we already have 
    // many open bins, to encourage consolidation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving "fragmented" space (1-9) which is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic preference: prefer residuals that are multiples of common item sizes (20, 25, 33).
    // Lower score for bins that align with high-probability item classes.
    let harmonic_alignment = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_alignment * 0.5;

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // Dynamic thresholding based on stream progression:
    // As the stream progresses, become more aggressive in packing tightly (penalize empty bins).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, lower penalty near the end of the stream.
        score += 40.0 * (1.0 - progress);
    }

    // If this is the only bin that fits the current item, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalty for bins that deviate significantly from the mean residual (encourages uniform packing).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residuals that are too small to fit typical items (< 10)
    // but large enough to waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have existing bins that can fit the item.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 30.0 + (open_bins_count as f64 * 2.5);
        }
    }

    // 4. Fitting Density: If this is the only bin that can fit the item, prioritize it to avoid
    // unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If our current bin is significantly worse than the mean, penalize it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // 6. Stream Progress: As we approach the end of the stream, prioritize tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to encourage tight packing.
    // We add the residual space itself to the score to penalize it.
    score += post_residual as f64 * 1.5;

    // 2. Lookahead Synergy: If the next item fits into the post_residual, 
    // heavily reward this bin to create a "perfect fit" pair.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 2.5;
        // Further refine: favor bins where the remaining space is minimized after the 2nd item
        score += (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Last Chance Heuristic: If this is the only bin that can fit the current item,
    // we must take it, so we force a very low score.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. Distribution Balancing: If the bin's residual is significantly lower than the 
    // global mean, we treat it as a "tight" bin and prioritize filling it to completion.
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // 5. New Bin Thresholding: 
    // If the bin is empty (new bin candidate), penalize it unless the current 
    // item is very large or we have many open bins that are already poorly filled.
    if bin_residual == bin_capacity {
        score += 85.0; // Baseline penalty for opening a new bin
        if open_bins_count > 0 {
            score += (mean_residual * 0.5);
        }
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize post_residuals that are too small to fit future items.
    // If post_residual is small but > 0, it creates "dead space" that is hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global State Balancing: Use mean_residual to avoid creating bins that are 
    // significantly emptier than the average.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: only do it if the average residual is already low.
        score += 50.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that bring the current bin's residual closer to the global mean.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // 4. Scarcity/Urgency: If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Dynamic Horizon: As we reach the end of the stream, prioritize packing tighter
    // to minimize the final bin count.
    if progress > 0.8 {
        score -= (100 - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating a "fragment" (small, unusable space)
    // If post_residual is small (e.g., < 10) but not 0, it is usually bad.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if the next item is large, prioritize keeping space in the current bin
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if we are mid-stream
            score += 20.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for new bins:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only want to open a new bin if the best existing fit is "bad" (e.g., leaves a very small fragment).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream
        score += 40.0 * (1.0 - progress);

        // If we have many open bins already, make opening a new one much more expensive
        score += open_bins_count as f64 * 5.0;
    } else {
        // Reward bins that bring the residual closer to the global mean (balancing)
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Heavily penalize bins that cannot fit the item (the logic should theoretically not reach here for fitting_bins)
    if bin_residual < item_size {
        score += 1000.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to keep bins packed tightly.
    // We favor bins where the post_residual is small (Best Fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Coupling: 
    // If the post_residual can accommodate the next item, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further favor bins that result in a "perfect" or "near-perfect" match for the next item.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Thresholding: Avoid creating "dead zones" (residuals between 1 and 9).
    // These are often unusable for the given item range (10-100).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // 4. New bin penalty: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it significantly
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 200.0;
        } else {
            score -= 50.0; // Force opening a new bin if nothing else fits
        }
    }

    // 5. Global state normalization: 
    // Discourage opening too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 10.0;

    // 6. Mean-Residual Balancing:
    // If this bin's residual is significantly higher than the average, penalize it to 
    // encourage filling lower-residual bins first.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is < 10, it is effectively dead space (since items are >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reduce the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Bin Pressure: Penalize opening new bins when many are already open.
    // This forces the algorithm to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // 5. Mean Residual Balancing: Favor bins that stay near the mean to keep distribution uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Progress Scaling: As we reach the end of the stream, prioritize closing bins
    // by penalizing empty space more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * post_residual as f64;

