    // Harmonic/Modulo logic: Favor bins that leave a residual which is a multiple of typical sizes (e.g., 20, 25).
    // This creates "clean" bins that are easier to fill later.
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.2;

    // Dynamic threshold: If we are late in the stream, be more aggressive with packing (lower score).
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // If this is a new bin, penalize it based on how many bins are already open.
    // This forces the algorithm to use existing bins unless the fit is extremely poor.
    if is_new_bin {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that are closer to the mean residual (maintains balanced bin levels).
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Critical constraint: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
