    // 4. Base score: Favor smaller post_residual (Best Fit principle).
    // We add a scaling factor to prefer bins that are already "fuller" (lower post_residual).
    let mut score = post_res + dead_space_penalty + lookahead_reward + pressure;

    // 5. New bin logic:
    // Only open a new bin if the current `bin_residual` is `bin_capacity` (the new bin candidate).
    // Heavily penalize opening a new bin unless the `post_residual` of all other options is very poor.
    if bin_residual == bin_capacity {
        // Only open new if we have too many open bins already or if fitting_bins_count is 0.
        // This acts as a "threshold" for opening new bins.
        score = 45.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
