    // penalize large post_residuals that could have been smaller to accommodate more items.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        }
    }

    // 3. Fragmentation penalty: Avoid creating "dead" space (small residuals < 10).
    // If a bin has a small residual that is likely unusable, we penalize it.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // 4. Global state adjustment: If we have many open bins, prioritize closing them 
    // (fitting into existing bins) by penalizing the new bin candidate.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with how many bins are currently available
        // to handle the item.
        score += (open_bins_count as f64 * 2.5) + (fitting_bins_count as f64 * 5.0);

        // Progression bias: Toward the end of the stream, be more conservative 
