pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // The core objective is to minimize post_residual (Best Fit).
    // We apply a non-linear penalty to small residuals that are likely to become "dead space".
    // A residual is "dead" if it is smaller than the smallest possible item (assumed ~10).
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post).powf(2.0) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead interaction: if a bin is empty (new bin), we evaluate the cost of opening it.
    // As the stream progresses, we become more conservative about opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_cost = if is_new_bin {
        // High base cost to open a new bin, weighted by the scarcity of fit options.
        // If fitting_bins_count is low, the penalty for a new bin is reduced.
        (45.0 + (progress * 20.0)) / (fitting_bins_count as f64 + 1.0).sqrt()
    } else {
        0.0
    };

    // Interaction between mean_residual and current post_residual.
    // We prefer bins that keep the global mean residual balanced.
    let balance_factor = (post - mean_residual).abs() * 0.5;

    // Lookahead: if the next item is large, favor bins with larger post_residuals 
    // to accommodate it (if this bin is the only one that could potentially fit it later).
    let next_item_pressure = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 0.8
    } else {
        0.0
    };

    let mut score = post + dead_space_penalty + new_bin_cost + balance_factor + next_item_pressure;

    // Final scaling: favor bins that are already partially filled to pack them tighter
    // as we reach the end of the stream (progress -> 1.0).
    if !is_new_bin {
        score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
