    // 1. Best-Fit Penalty: Penalize large post_residuals to keep bins tight.
    // We favor smaller post_residuals (the standard Best-Fit heuristic).

    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the fit is nearly perfect (post_residual very close to next_item_size)
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. New Bin Threshold: If this is an empty bin, penalize it unless the current 
    // fitting options are poor (e.g., all current fits leave awkward gaps).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no bins fit, new bin is mandatory; set base score to 0.0.
            score = 0.0;
        }
    } else {
        // 4. Distribution Balancing: Avoid creating bins with residuals significantly 
        // smaller than the global mean, as these become "dead" bins quickly.
        if (post_residual as f64) < mean_residual * 0.5 {
            score += 15.0;
        }

        // 5. Urgency: As we approach the end of the stream, favor utilizing 
        // existing bins over opening new ones.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We want the smallest residual that is non-zero (Best Fit),
    // but we heavily penalize very small residuals that create "dead space" (e.g., < 10).
    let mut score = post_residual as f64;

    if post_residual < 10 && post_residual > 0 {
        // Penalty for creating a "sliver" that is likely to remain empty
        score += 25.0;
    }

    // Lookahead logic: If the next item can fit in this bin, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }

    // If this is the only bin that fits the current item, prioritize it to avoid new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Global state awareness:
    // If we are late in the stream, be more aggressive about filling bins tightly.
    if progress > 0.8 {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // New bin logic:
    // Only open a new bin if we have many bins open already or if the fit is truly terrible.
    if is_new_bin {
        if open_bins_count == 0 {
            score = -100.0; // Always start first bin
        } else {
            // Penalty for opening a new bin is dynamic based on how many are already open
            // and how much space is currently wasted on average.
            score = 60.0 + (open_bins_count as f64 * 2.0) + mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish high post_residual (Best Fit strategy)
    // We want to minimize post_residual to pack bins tightly
    let mut score = post_residual as f64;

    // Penalty for opening new bins: scale by progress to be more conservative as the stream ends
    if is_new_bin {
        // As we reach the end of the stream, opening a new bin is increasingly costly
        // unless it's the only way to avoid a very poor fit.
        score += 40.0 * (1.0 - progress).powf(0.5);
    } else {
        // Reward bins that are closer to the mean residual to maintain balance
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * dev;

        // Lookahead heuristic: if next_item_size is large, avoid leaving a tiny residual
        // that is useless (e.g., < 10).
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size {
                // If the current bin will be too small for the next item, 
                // penalize it proportional to the waste created.
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Encourage using bins that are already partially filled if they fit well
    if fitting_bins_count > 0 && !is_new_bin {
        score -= 5.0 * (1.0 / (fitting_bins_count as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot fit common items)
    // We penalize residuals in the 1-9 range heavily as they are mostly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Harmonic Class Logic: Reward filling bins to specific "stable" fractions (e.g., 0, 25, 50)
    // We favor post_residuals that are multiples of 20 (creating larger, more usable chunks)
    let remainder = post_residual % 20;
    score += remainder as f64 * 0.5;

    // 3. Lookahead Integration: If next_item_size is large, avoid small post_residuals
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item
            score += 40.0;
        } else {
            // Reward keeping space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // 4. Density Balancing: If we have many open bins, prioritize tighter packing
    // If few bins fit the item, we are constrained; if many, pick the one that leaves the best remainder
    if fitting_bins_count > 0 {
        let fit_ratio = open_bins_count as f64 / fitting_bins_count as f64;
        score += fit_ratio * 5.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current best fit is truly abysmal
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very small
        // or if we have very few open bins (avoiding fragmentation early)
        if mean_residual > 20.0 || open_bins_count > 5 {
            score += 35.0;
        } else {
            score += 100.0;
        }
    }

    // 6. Progressive Strategy: As stream nears end, prioritize tighter packing (lower score)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space": If post_residual is small (1-9), it is likely to remain unused.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead optimization: If next_item_size is large, avoid creating a post_residual that is too small for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0;
    }

    // 3. Pressure management: If this is an existing bin (not a new one), reward fitting.
    // fitting_bins_count == 1 means this is the only bin that can take this item.
    if bin_residual < bin_capacity {
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else {
        // 4. Penalty for opening a new bin: Only open if forced or if current state is extremely inefficient.
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Global efficiency: Favor bins that keep the mean_residual high (balanced distribution).
    // This prevents "bin-packing" too tightly early on and leaving orphans later.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
