    // However, we penalize very small residuals (e.g., 1-5) as they create "dust" 
    // that is hard to fill later.
    if post_residual > 0 && post_residual < 6 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If a bin can fit the next item perfectly (or near perfectly),
    // prioritize it heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // If this bin is the only one that fits the current item, avoid opening a new one
        // unless the fit is truly abysmal.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 40.0;
        }
    }

    // 3. New Bin Penalty: Discourage opening a new bin unless existing bins are very full.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average space in existing bins is already tight
        // or if we are forced to (handled by the relative scoring).
        score += 35.0 + (mean_residual * 0.5);
    }

    // 4. Global progress scaling: As we approach the end of the stream, 
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Best-Fit Decreasing logic modulated by lookahead and bin density.

    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalize creating "dead space" (tiny gaps that are hard to fill).
    // Gaps between 1 and 9 are often unusable for items >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead mechanism: If next_item_size is large, prioritize keeping 
    // larger residuals open, otherwise favor tight packing.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if the bin won't be able to hold the next item
            score += 20.0 * (1.0 - progress);
        } else {
            // Reward if the bin can accommodate the next item
            score -= 15.0 * (1.0 - progress);
        }
    }

    // 3. Global state: If we have many open bins, prioritize filling existing ones.
    // If few bins are open, be more conservative about packing.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that can take this item; high priority.
        score -= 100.0;
    }

    // 4. Dynamic threshold for opening a new bin:
    // Only open a new bin if the current post_residual is very inefficient.
    if bin_residual == bin_capacity {
        // New bin penalty: only choose this if the average residual of 
        // existing bins is already very tight.
        score += 40.0 + (mean_residual * 0.5);
    }

    // 5. Packing density: Favor bins closer to the mean residual to keep distribution uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

