pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    // We penalize the post_residual quadratically to favor tight packing
    let mut score = (post_residual as f64).powf(1.5);

    // If it's a new bin, apply a dynamic penalty based on current efficiency
    // We only open a new bin if we cannot find a good fit elsewhere
    if is_new_bin {
        // Penalty scales with how much space we are wasting on average across existing bins
        // If mean_residual is low, we are packing well, so opening a new bin is expensive
        score += (mean_residual * 2.5) + (progress * 50.0);

        // If there are bins that could fit this item, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 150.0 / (fitting_bins_count as f64 + 1.0);
        }
    } else {
        // For existing bins, reward configurations that leave space for the next item
        // If the next item fits into the current post_residual, give it a massive priority boost
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.2;
        }

        // Penalize creating "dead zones" (residuals too small for common items, e.g., < 10)
        if post_residual > 0 && post_residual < 10 {
            score += 40.0 * (1.0 - progress);
        }
    }

    // Adjust score based on open bin count to prevent excessive fragmentation
    score += (open_bins_count as f64).powf(1.2) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
