    }

    // 2. Lookahead optimization: If a future item exists, reward bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bin that can also fit the next item
        } else {
            score += 10.0; // Penalize bin that will force a new bin for the next item
        }
    }

    // 3. Fragmentation control: If this is the last fitting bin, prioritize it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
