pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual gaps (classic Best-Fit logic)
    // We favor post_residual being as close to 0 as possible.

    // 2. Lookahead Matching (The "Aggressive" Component)
    // If next_item_size fits perfectly into the current post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 0.5;
    }

    // 3. Mean Residual Balancing
    // If the current bin's post_residual is significantly better than the global mean,
    // we prioritize it to keep the average bin density high.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // 4. Scarcity/Fitting Constraint
    // If this is the only fitting bin (fitting_bins_count == 1), we are forced to use it.
    // We reward this to prevent unnecessary opening of new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin Thresholding
    // If evaluating an empty bin (bin_residual == bin_capacity), penalize it unless 
    // the current fitting options are extremely poor (i.e., high post_residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0; // Must open a bin if none exist
        } else {
            // Only open a new bin if the best existing fit is still quite wasteful
            score += 40.0; 
        }
    }

    // 6. Progression scaling: towards the end of the stream, be more conservative with space
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
