pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, it's often better to 
    // leave it empty for a future perfect fit.
    if post_res > 0.0 && post_res < 15.0 {
        score += 20.0 * (1.0 - (post_res / 15.0));
    }

    // Lookahead logic: if the next item is large and won't fit in this post_residual,
    // penalize this bin to save space for the next item.
    if next_item_size > 0 {
        if (post_res as u32) < next_item_size {
            score += 35.0 * (1.0 - progress);
        }
    }

    // Dynamic pressure: as the stream progresses, discourage opening new bins (high residuals).
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy progress-based tax.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress * 0.5);
    }

    // Balance open bins: penalize bins that deviate significantly from the mean residual
    // to keep bins packed at similar levels (Best Fit Variance reduction).
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.2;

    // If this is the only bin that fits, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals that are "near-dead" (e.g., < 10) 
    // unless they perfectly fill the bin.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, reward this bin choice.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Harmonic Filling: Encourage bins to maintain residuals that are multiples of common item sizes (20, 25, 33).
    // This helps align future items with bin boundaries.
    let harmonic_penalty = ((post_residual % 20) + (post_residual % 25)) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Open-Bin Efficiency: Discourage opening a new bin if other bins are available.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 60.0;
        }
    } else {
        // 5. Last Chance Logic: If this is the only bin that fits the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Global Progression: As the stream nears the end, become more aggressive at closing gaps 
    // to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

