    // If post_residual is slightly smaller than next_item_size, it's a "bad" placement.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // 3. Dynamic Thresholding:
    // If this is a new bin, penalize it based on how many bins are already open 
    // and how much "room" is left in existing bins.
    if is_new_bin {
        // Only open a new bin if we are forced to or if existing bins are very full.
        if fitting_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
        // As the process nears completion, discourage opening new bins.
        score += (progress * 50.0);
    }

    // 4. Global State Calibration:
    // If the average residual is high, we are wasting space globally.
    // Prefer bins that bring the current bin's residual closer to the global mean.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Last resort bias: 
    // If this is the only bin that can fit the item, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
