    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Encourage filling bins to high capacity (Best-Fit principle)
    // We penalize high post_residual values to keep bins packed tightly.
    score += (post_residual as f64) * 0.5;

    // Lookahead logic: if next_item_size is large, favor bins that have space for it.
    // If post_residual is >= next_item_size, we effectively save a bin later.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalize if we block the next item from fitting here
            score += 20.0;
        }
    }

    // Handle new bin opening:
    // If bin_residual == bin_capacity, this is a "new bin" candidate.
    // We only want to open a new bin if the existing options are very poor (high score).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Force a high cost to open a new bin unless all existing fits are terrible.
            score = 45.0 + (mean_residual * 0.1);
        }
    }

    // Harmonic/Modulo consideration:
    // Aligning items to common divisors of 100 (e.g., 20, 25, 50)
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // Progression awareness:
    // Towards the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
