        score -= 15.0;
    }

    // 5. Global Efficiency: Penalize bins that deviate significantly from the mean residual
    // to maintain a consistent fill level across the bin set.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

