    // Penalize smaller residuals to prioritize tighter packing.
    let mut score = post;

    // If this is a new bin, apply a progress-dependent penalty.
    // Early in the stream, we are more aggressive at packing into existing bins.
    // Late in the stream, we are more willing to open new bins to clean up remaining space.
    if bin_residual == bin_capacity {
        score = (capacity * 0.75) + (progress * capacity * 0.4);
    } else {
        // Non-linear coupling: penalize bins that leave behind "dead space" that
        // is too small for the next item or the average item size.
        // We calculate a "waste" penalty based on the post_residual.
