            0.0
        };

        // Encourage filling bins that are already "half-full" or more to 
        // minimize the total number of active bins.
        let usage_factor = (capacity - bin_residual as f64) / capacity;
        let density_reward = -15.0 * usage_factor * (1.0 - progress);

        score += waste_penalty + density_reward;

        // If this is the last fitting bin, give it a slight preference to avoid 
        // opening a new bin prematurely.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
