}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but unusable (1-9)
    // as they create "dust" that cannot accommodate the minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly in the 
    // remaining space, prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Reward exact fit (gap 0) or small gap, penalize large gaps for next item
            score -= (50.0 / (gap as f64 + 1.0));
        }
    }

    // 3. Density Balancing: If we are late in the stream, prioritize closing bins
    // by minimizing the post_residual aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 4. New Bin Threshold: If this is an empty bin, only pick it if the penalty 
    // for using existing bins is extremely high.
    if bin_residual == bin_capacity {
