        score = 45.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this is the last fitting bin, provide a slight bias to use it
        // to avoid opening a new one unnecessarily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Mean Residual Coupling: Penalize bins that deviate significantly from the 
    // average fill level to maintain uniform bin usage (Best-Fit variant).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

