    }

    // Residual balancing: Avoid bins that deviate significantly from the mean
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Last chance logic: If this is the only bin that fits the item, make it highly desirable
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
