        if next_item_size > 0 {
            let space_needed_for_next = next_item_size as f64;
            // If this bin becomes too small for the next item, penalize slightly
            if (post_residual as f64) < space_needed_for_next && post_residual > 0 {
                score += (space_needed_for_next - post_residual as f64) * 0.3;
            }
        }

        // Penalize opening too many bins by favoring bins that are already well-utilized
        // Use mean_residual to identify "empty" bins vs "full" bins
        let utilization_penalty = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= utilization_penalty * 10.0;
    }

    // Adjust for stream tail: In the final 10% of items, be more aggressive with new bins to clear items
    if progress > 0.9 && !is_new_bin {
        score += 5.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

