    // 4. Fitting Bin Scarcity: If this is the only bin that can fit the item, lower the penalty to accept the fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current post_residual is significantly lower than the mean_residual,
    // it suggests we are filling this bin better than the average, so reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progress Scaling: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score, so we reward placements that align with the next item
    // or leave a remainder that is highly usable.
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0;
        } else {
            score -= 50.0;
        }
    }

    // 2. Lookahead optimization: If the post_residual can fit the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0;
        } else {
            // Penalize creating "dead space" that cannot fit the next item
            score += 20.0;
        }
    }

    // 3. Balance towards filling bins tightly (Best-Fit principle)
    // Reward bins that end up closer to the current mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Pressure to consolidate: If we have many open bins, penalize leaving large residuals
    if open_bins_count > 5 {
        score += (post_residual as f64) * 0.8;
    }

    // 5. Finality constraint: If this is the last chance to fit an item into an existing bin, 
    // favor it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize extremely small residuals (dead space).
    // A residual of 1-4 is often unusable, so we inflate its score to push it away.
    if post_residual > 0 && post_residual <= 4 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State: If we have many open bins, we become more conservative (trying to fill existing ones).
    // If we have few open bins, we are more willing to start a new one to keep residuals high.
    let bin_pressure = (open_bins_count as f64) / 10.0;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress and current open bin count.
        score += 30.0 + (progress * 20.0) + (bin_pressure * 5.0);
    } else {
        // Reward for using existing bins, dampened by the mean residual of the system.
        score -= (bin_capacity as f64 - mean_residual) * 0.2;
    }

    // 4. Criticality: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Dynamic Thresholding: As we approach the end of the stream, prioritize tight packing.
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the new bin candidate (where residual == capacity) significantly 
    // early in the stream, but allow it to be chosen if no good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin { 45.0 + (progress * 20.0) } else { 0.0 };

    // Primary objective: Minimize post_residual (Best Fit).
    // We apply a non-linear scaling to the post_residual to favor tighter packing.
    let fit_score = post.powf(1.4);

    // Lookahead influence: If the next item is large, avoid leaving small residuals 
    // that cannot accommodate it (fragmentation penalty).
    let next_item = next_item_size as f64;
    let fragmentation_penalty = if next_item > 0.0 && post < next_item && post > 0.0 {
        (next_item - post) * 2.5
    } else {
        0.0
    };

    // Coupling with open bins: As the stream progresses, penalize excessive 
    // bin usage to encourage consolidating items into fewer bins.
    let bin_count_penalty = (open_bins_count as f64).powf(1.1) * (0.5 + progress);

    // Reward bins that have a residual close to the mean, reducing variance in bin fullness.
    let variance_penalty = (post - mean_residual).abs() * 0.2;

    // Final score: Lower is better.
    base_penalty + fit_score + fragmentation_penalty + bin_count_penalty + variance_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic scaling: penalize post_residuals that leave small, unusable gaps (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // 3. Lookahead synergy: If the next item fits perfectly in the current post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 4. New bin management: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the item is very large
        // and would create a highly fragmented bin if placed elsewhere.
        if open_bins_count > 0 {
            let threshold = 60.0 + (mean_residual * 0.5);
            score += threshold; 
        }
    } else {
        // 5. Fitting constraint: If this is the only bin that fits, prioritize it heavily
        if fitting_bins_count == 1 {
            score -= 50.0;
        }
    }

    // 6. Distribution balance: Favor bins that keep the mean residual closer to a "sweet spot" (e.g., 20-30)
    // This prevents filling bins to the brim too early if it forces sub-optimal future moves.
    let target_residual = 25.0;
    score += (post_residual as f64 - target_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit strategy).
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the range (0, 10),
    // it is highly likely to be unusable for future items (min size 10).
    // Penalize heavily to push items into bins that leave larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open bin pressure: If we have many open bins, penalize opening a new one.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) * (1.0 + progress);
    }

    // 3. Lookahead optimization: If the next item is large, prefer bins 
    // that leave enough room for it.
    if next_item_size > 0 && next_item_size > post_residual {
        // If the current placement makes the next item impossible to fit, 
        // add a penalty relative to the size of the next item.
        score += next_item_size as f64 * 0.5;
    }

    // 4. Fitting constraint: If this is the last fitting bin, we should 
    // treat it with higher priority unless it creates a very small gap.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // 5. Mean residual balancing: Encourage using bins that are closer to the 
    // average fullness to keep the "fill level" consistent across bins.
    let dev_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

