            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // 3. Mean residual balancing: Prefer bins that stay close to the global mean to maximize future packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
