    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. Penalty for opening a new bin if other bins can fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0;
    }

    // 3. Lookahead optimization: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
