    if mean_residual > 30.0 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // prioritize closing bins (minimizing post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
