    }

    // 7. Favor bins that are already partially filled over fresh ones 
    // to maintain a low open_bins_count.
    if bin_residual < bin_capacity && bin_residual > item_size {
        score -= 10.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual is better)
    let mut score = post_res.powf(1.5);

    // Penalty for creating a "fragmented" bin: if post_residual is small but not zero,
    // it effectively kills future utility for large items.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 * (1.0 - (post_res / 20.0));
    }

    // Lookahead logic: if the next item fits into this post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
