    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress.powf(0.5));
    }

    // Balance against mean_residual: avoid outlier bins that deviate significantly 
    // from the average packing density to keep the profile consistent.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.2;

    // Favor bins that have higher utilization (lower post_residual) when we have
    // many open bins, to encourage consolidation.
    score += (open_bins_count as f64) * (post_res / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
