    // to prevent fragmentation at the end of the packing process.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (25.0 + (35.0 * progress.powi(2)));

    // Favor bins where the post_residual is small (tight fit), but penalize extreme tightness (0)
    // if the next item is large, as it creates "orphan" space that cannot accommodate future items.
    let tightness_score = if post == 0.0 { 5.0 } else { post.powf(1.1) };

    // Coupling: If we have many fitting bins, we can afford to be choosier.
    // If we have few, we should prioritize packing into an existing bin to avoid new_bin_penalty.
    let availability_factor = (fitting_bins_count as f64).ln_1p();

    // Lookahead logic: If the next item is large (> 50), penalize bins that leave just enough 
    // space to be useless for the next item but too small for other potential items.
    let mut lookahead_penalty = 0.0;
