        lookahead_penalty = (next_item_size as f64 - post) * 0.5;
    }

    // Combine metrics:
    // We aim for a low score. New bin penalty is the base, adjusted by fit quality and lookahead.
    let score = new_bin_penalty + tightness_score - (availability_factor * 2.0) + lookahead_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
