    // Reward bins that have residuals closer to the mean_residual to keep bin states uniform (Best-Fit principle).
    let uniformity_penalty = (post - mean_residual).abs() * 0.5;

    // Favor bins that are "last chance" (fitting_bins_count == 1) to avoid opening new bins unnecessarily.
    let last_chance_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -25.0
    } else {
        0.0
    };

    // The base score is the post_residual (Best Fit).
    // We want to minimize the post_residual, but heavily adjust based on the context.
    let score = post + new_bin_penalty + next_item_fit_penalty + uniformity_penalty + last_chance_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We heavily penalize the "New Bin" (post_residual == 100 - item_size)
    // unless the number of open bins is very small.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.5);
    }

    // 2. Harmonic Class Logic: Reward residuals that match potential future item sizes.
    // If post_residual is a multiple of next_item_size, we create a "perfect" slot.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        // Reward cases where the next item fits perfectly or leaves minimal space.
        if remainder == 0 {
            score -= 15.0;
        } else if remainder < (next_item_size / 3) {
            score -= 5.0;
        }
    }

    // 3. Last Chance Heuristic: If this is the only bin that fits, prioritize it
    // to avoid the penalty of opening a brand new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 4. Fragmentation Control: Penalize residuals that are too small to fit any
    // likely future item (e.g., < 10) unless it's a perfect fill (0).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // 5. Density Balancing: If the current bin is significantly emptier than the
    // mean, prefer filling it to keep the average residual consistent.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Progression Scaling: As the stream nears the end, be more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        if bin_residual == bin_capacity {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
