    // 2. Lookahead Integration: If next_item_size fits in the post_residual,
    // we heavily favor this bin to avoid fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
    }

    // 3. Fragmentation Penalty: Penalize tiny residuals that are unlikely to fit future items (1-9).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Global State: If we have many open bins, prioritize closing gaps (tightening).
    // If we have very few bins, prioritize keeping bins open for future items.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // 5. New Bin Logic: If we are considering a brand new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are "too full" to handle the lookahead
        // or if we have very few open bins relative to the remaining items.
        if fitting_bins_count > 0 {
            score += 60.0; // Heavy penalty for opening new bin if existing bins can fit
        } else {
            score -= 10.0; // Reward opening new bin if no other choice
        }
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate too far from the average residual.
    // This encourages a uniform fill rate across all bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual: we want to minimize this (Best Fit principle).
    // Penalize large post_residual (wasted space) quadratically.
    let mut score = post_res.powi(2);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases as the stream progresses to allow for more flexibility
    // when we are nearing the end of the input sequence.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64 * 1.5) * (1.0 - (progress * 0.5));
    }

    // Lookahead logic: if the next item is large, penalize bins that would leave
    // a post_residual too small to accommodate the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += (next_item_size as f64 - post_res) * 2.5;
        }
    }

    // Interaction with mean_residual: discourage creating bins that deviate 
    // significantly from the current global average efficiency.
    let deviation = (post_res - mean_residual).abs();
    score += deviation * 0.8;

    // Favor bins that are "tight": if fitting_bins_count is low, 
    // we want to prioritize using current bins to avoid opening new ones.
    if fitting_bins_count > 0 {
        score -= (1.0 / fitting_bins_count as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

