    if bin_residual == bin_capacity {
        // If existing bins have plenty of space, penalize opening a new one.
        score += mean_residual * 0.8;

        // If only one bin could fit the current item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // 6. Harmonic Class Logic:
    // Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
