    };

    // Final score: prioritize tight fits (low post_residual) while managing lookahead and growth
    // Lower is better: we subtract rewards and add penalties
    let score = waste_penalty + new_bin_penalty - lookahead_reward + density_bias;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
