    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 3. Lookahead Optimization: If the next item cannot fit in this bin, 
    // prioritize keeping the residual large enough to accommodate the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Open Bin Pressure: As the stream progresses, discourage opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that scales with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0) + (progress * 20.0);
    }

    // 5. Fragmentation Avoidance: If this is the only bin that can fit the item, 
    // reward it to prevent unnecessary bin creation, unless it's a terrible fit.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 10.0;
    }

    // 6. Mean Balancing: Discourage creating bins that are significantly 
    // more empty than the current average.
    if post_residual > (mean_residual as u32 + 10) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin:
    // If this is a new bin, apply a heavy penalty unless it's the only choice.
    if bin_residual == bin_capacity {
        score += 45.0; 
