    // 2. Lookahead Matching (The "Tight-Fit" Logic):
    // Reward bins where the post_residual is close to the next_item_size (Best Fit Lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.8;

        // Bonus for creating a bin that can definitely fit the next item.
        if post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // 3. Fragmentation Avoidance:
    // Penalize small residual space that cannot fit common small items (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global Density Balancing:
    // If the mean residual of current bins is high, we are being too loose;
    // force tighter packing by penalizing higher post_residuals.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // 5. Urgency Calibration:
    // If this is the only bin that fits, prioritize it heavily to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress Normalization:
    // Toward the end of the stream, prioritize clearing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
