        }

        // Global state adjustment: If we have many bins open, try to pack tighter into existing ones.
        if open_bins_count > (total_items / 50).max(5) {
            score -= (bin_capacity as f64 - mean_residual) * 0.1;
        }

        // Critical threshold: If this is the only bin that can fit the item, prioritize it heavily
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

