    // Adjust based on the global state of bins to prevent fragmentation.
    // Higher mean_residual implies we have plenty of space, so we can afford 
    // to be pickier about where we place the current item.
    score += (mean_residual - post) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
