    // Try to keep post_residuals aligned with common divisors of 100 (e.g., 20, 25, 50).
    // This reduces the chance of leaving 'dead' space that cannot fit future items.
    let rem = post_residual % 25;
    score += (rem as f64).powi(2) * 0.1;

    // 4. Open-bin management:
    // If this is the only fitting bin, give it a significant bonus to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New-bin threshold:
    // Discourage opening a new bin unless the current best fit is objectively terrible.
    if bin_residual == bin_capacity {
        // If we have many open bins, penalize opening a new one heavily.
        score += (open_bins_count as f64) * 15.0;

        // As the stream progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    // 6. Mean-residual correction:
    // Penalize bins that deviate too far from the average state of the system.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

