            score -= (next_item_size as f64) * 0.3;
        }
    }

    // Interaction 2: Stream progress coupling.
    // As the stream progresses, we become more conservative about opening new bins.
    // New bin candidate is when bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // As we reach the end of the stream, penalize opening new bins heavily.
        score += (100.0 * progress).powi(2);

        // If there are other bins that could fit this item, penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Interaction 3: Mean residual balancing.
    // Penalize bins that deviate too far from the average residual to maintain uniformity.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    // Interaction 4: Non-linear penalty for "dead space".
    // Small residuals that are too small to fit common items (e.g., < 10) are often wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that minimize post_residual (tightest fit)
    // 2. Harmonic penalty: heavily penalize small fragments that are unlikely to fit future items.
    // If post_residual is in the range [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Thresholding: Avoid opening a new bin unless the existing fits are extremely poor.
    // If we are considering a new bin (bin_residual == bin_capacity), apply a penalty 
    // proportional to the number of open bins to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Residual Balancing: If the current bin's residual is significantly above 
    // the global mean, favor placing the item here to equalize the distribution.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Last-Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it to avoid opening an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 7. Progression scaling: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) over keeping bins open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
