    // Penalize creating "dead zones" (residuals that are too small to fit common items).
    // We heavily penalize small residuals (1-9) as they are likely to remain permanently empty.
    let dead_zone_penalty = if post < 10.0 && post > 0.0 { 50.0 / (post + 0.1) } else { 0.0 };

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual < next_item_size, we effectively force an extra bin opening later.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size - post_residual) as f64 * 1.5
    } else {
        0.0
    };

    // Global state awareness:
    // As the stream progresses, prioritize closing bins (lower mean_residual) to consolidate space.
    let consolidation_pressure = (mean_residual - post) * progress;

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), set a threshold.
    // Only open a new bin if the current best fit is extremely poor (post_residual is very small).
    let is_new_bin = bin_residual == bin_capacity;
    let base_score = if is_new_bin {
        // High penalty to prevent opening new bins unnecessarily.
        // Penalty decreases as the number of open bins increases (to avoid fragmentation)
        // and increases as we approach the end of the stream.
        15.0 + (open_bins_count as f64 * 0.5) + (progress * 20.0)
    } else {
        post + dead_zone_penalty + lookahead_penalty + consolidation_pressure
    };

    base_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
