    // 1. Prioritize bins that leave the smallest residual (Best Fit).
    // 2. Penalize opening new bins unless the fit in existing bins is poor.
    // 3. Use lookahead (next_item_size) to favor bins that can accommodate the next item.

    let mut score = post_residual as f64;

    // Penalty for creating 'dead zones' (residual space too small for any likely item)
    // If post_residual is < 10, it's likely unusable.
    if post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the post_residual space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Dynamic threshold for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very tight (e.g., < 15)
        // or if there are no other viable bins.
        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 100.0;
        } else {
            score += 40.0;
        }
    }

    // Global state scaling:
    // As the stream progresses, prioritize closing bins to reduce open_bins_count.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // Reward bins that are already partially filled (Best Fit principle)
    // but penalize them if they are nearly full and would block future packing.
    if post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize values below the expected average of remaining item sizes (approximated by mean_residual).
    if post_res > 0.0 && post_res < mean_residual {
        score += (mean_residual - post_res).powf(1.5);
    }

    // Lookahead logic: If the next item is large, avoid leaving a residual that is slightly too small for it.
    if next_item_size > 0 && post_res < next_item_size as f64 && post_res > 0.0 {
        score += (next_item_size as f64 - post_res) * 2.5;
    }

    // Dynamic thresholding for new bin creation:
    // As the stream progresses, become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other bins can fit the item.
        // This penalty increases as the stream approaches its end.
        let new_bin_penalty = 15.0 + (fitting_bins_count as f64 * 10.0) + (progress * 40.0);
        score += new_bin_penalty;
    } else {
        // Reward filling existing bins as the stream nears completion
        score -= (progress * 10.0);
    }

    // Penalize fragmented state: if many bins are open, prioritize closing them by filling them
    score += (open_bins_count as f64).sqrt() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead: penalize bins that cannot fit the next item if we have a good fit
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Significant penalty for stranding a bin that cannot accommodate the next item
            score += (bin_capacity - post_residual) as f64 * 0.5;
        } else {
            // Reward bins that can fit the next item
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        }
    }

    // 3. Harmonic class awareness: Favor tight fits (small post_residual)
    // If post_residual is near 0, 5, or 10, it's likely a good "harmonic" fit for future items
    let remainder = post_residual % 10;
    if remainder == 0 {
        score -= 15.0;
    } else if remainder > 8 {
        score += 10.0;
    }

    // 4. Thresholding for new bins: 
    // If this is a new bin (bin_residual == bin_capacity), make it expensive unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced to open a new bin
        } else {
            // Heavily penalize opening a new bin if other bins can fit the item
            score = 50.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Favor bins that are already "half-full" to keep open bin count low
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 5.0;
    }

    // 5. Progression damping: As we near the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Avoidance: Penalize residuals that are too small to fit common items
    // If post_residual is in the range [1, 9], it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Penalize opening a new bin if other options exist.
    // If current bin is a new bin (residual == capacity), penalize based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If we have other fitting bins, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Tight Fit Reward: If the item fills the bin perfectly or near-perfectly, reward it.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // 5. Global Efficiency: If the bin is becoming too empty compared to the mean, punish it.
    if (post_residual as f64) > mean_residual && open_bins_count > 1 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins tightly packed.
    // We favor smaller post_residuals (Best Fit).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the post_residual can accommodate the next item, 
    // heavily reward this bin to minimize future bin openings.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
        // Further reward if it leaves a very tight remaining space after the next item.
        let potential_residual = post_residual - next_item_size;
        if potential_residual < 10 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless the current 
    // best fit is very poor (i.e., leaves a 'dead' space that can't fit upcoming items).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already quite small
        // or if we have very few bins, otherwise force usage of an existing bin.
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 40.0; 
        } else {
            score += 60.0;
        }
    }

    // 4. Scarcity Constraint: If this is the last bin that can fit the item, 
    // prioritize it to avoid wasting the opportunity.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Efficiency: As we approach the end of the stream, 
    // be more aggressive about packing to avoid stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit logic)
    // Already in 'score', but we weight it to encourage tight packing.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin utilization (Two-Item Lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Thresholding: 
    // If we have many open bins, penalize opening a new one heavily.
    // If we are near the end of the stream, prioritize closing existing bins.
    if is_new_bin {
        score += (open_bins_count as f64 * 2.5) * (1.0 + progress);
        if fitting_bins_count > 0 {
            score += 50.0; // Strong penalty for opening new bin if others exist
        }
    }

    // 4. Global State Balancing:
    // If the bin's residual is significantly lower than the mean_residual, 
    // it's a "tighter" bin; we prefer placing into bins that are already 
    // tighter than the average to keep the remaining bins "open" for larger items.
    if !is_new_bin {
        if (post_residual as f64) < mean_residual {
            score -= 10.0 * (1.0 - progress);
        }
    }

    // 5. Last Chance Heuristic:
    // If this is the only bin that can fit the item, prioritize it to avoid forced new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post-residual (Best Fit)
    // We apply a non-linear penalty for creating "dead space" (small residuals that are hard to fill)
    // The penalty is modulated by the remaining stream progress.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5) * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead interaction: If the next item is large, prioritize keeping space open.
    // If next_item_size is 0, we are at the end, so maximize space usage.
    let lookahead_weight = if next_item_size > 0 {
        let diff = (next_item_size as f64 - post).max(0.0);
        diff * 0.5
    } else {
        -post * 0.1
    };

    // Penalty for opening new bins: if fitting_bins_count > 0, we penalize the new bin option.
    // We scale this penalty by the current mean_residual to prevent over-filling bins 
    // when we have plenty of capacity elsewhere.
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
        100.0 + (mean_residual * 2.0)
    } else {
        0.0
    };

    // Coupling: Use post_residual as the primary anchor, add non-linear surface constraints.
    let score = post + dead_space_penalty + lookahead_weight + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Archetype: Harmonic classes (Best-Fit Decreasing variant).
    // Penalize small residuals that are unlikely to fit future items (dead space).
    // Reward bins that leave space matching the likely size of the next item.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is too small to fit common items (e.g., < 10),
    // we heavily penalize it unless it's exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size fits in the post_residual,
    // we reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 3. Fragmentation avoidance: Penalize opening a new bin if other bins can fit the item.
    // If this is a new bin (residual == capacity) but fitting_bins_count > 0, penalize heavily.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 100.0;
    }

    // 4. Distributional balance: If the mean_residual is high, we are currently "loose".
    // We should favor tighter fits (lower post_residual) to bring the mean down.
    if mean_residual > 30.0 {
        score += (post_residual as f64) * 0.5;
    }

    // 5. Progress-based scaling: As we reach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late stage: strongly prefer smaller post_residuals to finish bins.
        score -= (100 - post_residual) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
