    // we only return a low score if the current mean_residual is very low (bins are full).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are near capacity
        score += 40.0 + (mean_residual * 2.0);
    } else {
        // Favor bins that maintain the mean residual
        score += (post_residual as f64 - mean_residual).abs();
        score += open_bin_penalty * 0.1;
    }

    // 5. Last Chance Heuristic: If this is the only bin that fits the item,
    // we lower the score to prioritize using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

