    }

    // 3. Balance the number of open bins.
    // If the bin is new (bin_residual == bin_capacity), penalize opening it
    // unless we have very few options or the current bin is a perfect fit.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 0.5);
    }

    // 4. Tightness objective: Favor bins where the post_residual is close to the mean
    // of all open bins, keeping the bin utilization profile uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

