    // This penalty scales down as we approach the end of the stream (progress -> 1.0).
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post) * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Favor bins that align with the next item size (Lookahead coupling).
    // If post_residual is close to next_item_size, we reward the bin.
    let lookahead_alignment = if next_item_size > 0 {
