    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // but reward those that leave a remainder that fits the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // 2. Harmonic Class Logic: Reward residuals that align with common item size multiples (e.g., 20, 25, 50).
    // This reduces fragmentation by leaving "round" numbers for future items.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.2;

    // 3. Fragmentation Control: If this is the last fitting bin, prioritize it heavily 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Threshold: If we are considering a new bin, apply a high base cost
    // to force the algorithm to fill existing bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Adjust new bin cost based on stream progression (late game: be more aggressive)
        score -= (step_index as f64 / total_items as f64) * 10.0;
    }

    // 5. Mean Residual Balancing: Penalize bins that deviate significantly from the mean
    // to keep the fill-levels of bins relatively uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize "Dead Space" (gaps < 10 are generally unusable given the item range 10-100)
    // Small residuals are the primary enemy of packing efficiency.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty proportional to current open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 3. Lookahead integration: If the next item is large, avoid leaving a small gap now.
    // If next_item_size > post_residual, the current placement is "blocking" the next item.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 30 {
        score += 30.0;
    }

    // 4. Fitting constraints: Reward bins that are "tight" fits for the current item
    // to keep larger gaps available for future, larger items.
    // We prioritize bins that leave a post_residual close to the mean_residual of other bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Final adjustment based on stream progression
    // As the stream nears the end, be more aggressive at filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: Lower post_residual is generally better (tighter packing).
    // 2. Penalty for creating "dead space": If post_residual is between 1 and 9, 
    //    it is likely unusable for future items (min size 10), so heavily penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic: If the next item fits perfectly into the current post_residual, 
    //    heavily reward this bin to clear it out.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one.
    //    If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Balance residuals: Avoid bins that deviate significantly from the mean_residual
    //    to keep the packing density uniform across active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Last Chance heuristic: If this is the only bin that can fit the item, 
    //    strongly prefer it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating a new bin: Only open if forced or if current options are abysmal.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity,
            // unless the remaining items are scarce.
            score += 150.0 * (1.0 - progress);
        } else {
            score = 0.0; // Must open new bin if no others fit.
        }
    } else {
        // Lookahead heuristic: If the next item fits better in this residual, prioritize this bin.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Good fit for next item: reward this placement.
                score -= 25.0;
            } else if post_residual > 0 && post_residual < 10 {
                // Bad fit: creating a tiny "sliver" that is likely unusable.
                score += 40.0;
            }
        }

        // Global state consideration: If we have many open bins, prioritize filling the ones 
        // that are already most empty to consolidate space.
        let residual_ratio = bin_residual as f64 / bin_capacity as f64;
        if residual_ratio > mean_residual / bin_capacity as f64 {
            score -= 10.0;
        }

        // Urgency factor: As we near the end of the stream, tighten the fit requirements.
        if progress > 0.8 {
            score += (post_residual as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
