    let post = post_residual as f64;

    // Base score is the residual space remaining (Best Fit heuristic base)
    let mut score = post;

    // Penalty for leaving small, unusable gaps (1..10) that are unlikely to be filled
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, reward this bin
    if next_item_size > 0 && (post_residual >= next_item_size) {
        score -= 40.0 * (1.0 - (next_item_size as f64 / (post + 0.1)));
    }

    // Dynamic adaptation: as the stream progresses, prioritize closing bins over opening new ones
    // We normalize the influence of the number of open bins relative to progress
    let open_bin_penalty = (open_bins_count as f64) * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty that decreases
    // as we reach the end of the stream (to ensure all items fit)
    if bin_residual == bin_capacity {
        score += 50.0 * (1.0 - progress) + open_bin_penalty;
    } else {
        // If fitting_bins_count is 1, this bin is the only option; reward it to prevent premature new bin opening
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Penalize bins that deviate significantly from the mean_residual to keep bin usage uniform
        let deviation = (post - mean_residual).abs();
        score += 0.5 * deviation;
    }

    score
}

