        score += (post_residual as f64 - mean_residual) * 1.2;
    }

    // 5. Critical Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // 6. Progressive Tightening: As the stream nears the end, become more aggressive 
    // about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the remaining space. Lower is better (Best Fit).
    // Penalize small post_residuals that create "dead space" (e.g., < 10, too small for any item).

    let mut score = post_residual as f64;

    // Penalty for creating unusable space (1..9 range is often wasted)
    if post_residual > 0 && post_residual < 10 {
