    }

    // Global state: If we are nearing the end of the stream, prioritize aggressive filling.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 20 {
        score -= 15.0;
    }

    // Penalize opening a new bin if other bins are available
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the current fit quality is very poor (high post_residual)
            // or if we have very few bins open.
            score += 30.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that are "tight" relative to the mean residual of other bins
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Criticality: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

