    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        150.0 * (1.0 - progress).powf(0.5)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: penalize large post_residuals (dead space).
    // Coupling with next_item_size: if the next item is large, prioritize leaving enough space.
    let lookahead_penalty = if next_item_size > 0 {
        let tightness = (next_item_size as f64 - post_res).max(0.0);
        tightness * 0.5
    } else {
        0.0
    };

    // Encourage filling bins that are already "tight" to minimize open bins count.
    // We use the mean_residual to identify bins that are currently under-utilized.
    let utilization_pressure = if !is_new_bin {
        (post_res - mean_residual).powi(2) * 0.01
    } else {
        0.0
    };

    // The core heuristic: prioritize the smallest post_residual (Best Fit),
    // modulated by the progression and lookahead dynamics.
    let mut score = post_res + new_bin_penalty + lookahead_penalty + utilization_pressure;

    // Discourage creating "unusable" small gaps (e.g., < 10) unless it's a perfect fit.
    if post_res > 0.0 && post_res < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins where post_residual is minimal (tightest fit).
    // We already start with post_residual, which inherently favors Best-Fit.

    // 2. Penalty for creating "dead space": if the post_residual is too small to fit any 
    // likely future items (e.g., < 10), it becomes a "sliver" that is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: if next_item_size exists, prefer bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that leave room for the next item
        } else {
            score += 10.0; // Penalize bins that block the next item
        }
    }

    // 4. Harmonic/Modulo pressure: favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20 or 25), increasing the probability of perfect packing.
    let residual_mod = (post_residual % 20) as f64;
    score += residual_mod * 0.5;

    // 5. Threshold control for opening new bins vs filling existing ones.
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // the current fitting_bins_count is low or the residual is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
