    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the current fit is extremely poor for existing bins.
    if bin_residual == bin_capacity {
        // If there are already many open bins, penalize opening a new one.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Favor bins that bring the mean residual closer to a target of 15-20,
        // which provides flexibility for future items.
        let deviation = (post_residual as f64 - 15.0).abs();
        score += deviation * 0.2;
    }

    // 4. Scarcity Factor: If this is the only bin that can fit the item, 
    // heavily favor using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progress Normalization: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to completion.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin: base cost is high, reduced if open_bins_count is low
        // or if fitting_bins_count is 0 (forced).
        score = 85.0 + (open_bins_count as f64 * 0.5);
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else {
        // Best Fit Decreasing logic: favor small post_residuals (tight packing)
        // Penalize leaving space smaller than the smallest likely items (e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // Lookahead: reward bins that leave exactly enough space for next_item_size
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual > next_item_size {
                // Reward bins that have just enough room for the next item
                score += (post_residual - next_item_size) as f64 * 0.2;
            } else {
                // Cannot fit next item: slight penalty
                score += 5.0;
            }
        }

        // Penalty for bins that deviate significantly from the global mean_residual
        // This encourages uniform filling across all open bins
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // Progression weight: as we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins where post_residual is minimized.
    // We heavily penalize large post_residuals (wasted space).
    score += post_residual as f64 * 2.5;

    // 2. Lookahead optimization: 
    // If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Penalty for "Last Chance" bins:
    // If this is the only bin that can fit the item, prioritize it to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global state awareness:
    // If the current bin is nearly empty compared to the mean residual of other bins,
    // discourage using it unless necessary, to keep bins packed consistently.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        if (bin_capacity - post_residual) < (bin_capacity as f64 - mean_residual) as u32 {
            score += 40.0;
        }
    }

    // 5. Dynamic time horizon:
    // As the stream progresses, become more aggressive about filling bins (Best-Fit)
    // to avoid leaving too many bins partially full at the end of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    // 6. Penalty for creating "orphaned" small residuals (fragmentation):
    // Residuals between 1 and 9 are often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize the creation of a new bin (bin_residual == bin_capacity)
    // The penalty decreases as we reach the end of the stream to allow for final consolidation
    let new_bin_penalty = if bin_residual == bin_capacity {
        15.0 * (1.0 - progress).powf(0.5)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: favor small post_residual (tightest fit)
    // We add a non-linear penalty for small post_residuals that are "unusable" 
    // (e.g., < 10, because items are >= 10 in this scenario).
    let tightness_penalty = if post < 10.0 {
        20.0 - (post * 2.0)
    } else {
        post * 0.1
    };

    // Coupling with next item: If we can fit the next item in the remaining space, 
    // reward this bin choice to consolidate items.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -12.0 * (1.0 - (post - next_item_size as f64) / 100.0)
    } else {
        0.0
    };

    // Penalty for increasing open_bins_count when many bins are already open
    let sprawl_penalty = (open_bins_count as f64).powf(1.2) * 0.5;

    // Combine factors
    // Lower score is better.
    new_bin_penalty + tightness_penalty + lookahead_reward + sprawl_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (small residues that are hard to fill)
    // We penalize residues in the range [1, 9] heavily as they are likely useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin density (Best Fit with Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. New Bin Handling:
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the item is very large or no other bins are available.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one could fit the item.
            score += 150.0;
        } else {
            // If no existing bin fits, opening a new one is mandatory.
            score -= 10.0;
        }
    }

    // 4. Harmonic/Modulo logic:
    // Favor bins that leave a residual which is a multiple of 10, 
    // as these are statistically more likely to accommodate future items in common distributions.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // 5. Global density pressure: 
    // If the number of open bins is high relative to the progress, 
    // force tighter packing by penalizing loose fits.
    let progress = step_index as f64 / total_items as f64;
    if (open_bins_count as f64) > (progress * 10.0 + 2.0) {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
