pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) which are hard to fill given the input range (10-80).
    // Small residuals are only good if they are zero (perfect fit).
    let gap_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_residual as f64) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post_residual as f64) * 0.5
    } else {
        0.0
    };

    // Dynamic threshold: As the stream progresses, become more aggressive about filling existing bins
    // to keep the bin count low.
    let completion_pressure = (1.0 - progress) * (open_bins_count as f64 * 2.0);

    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the existing fits are significantly worse.
    let base_score = if bin_residual == bin_capacity {
        // High penalty for opening a new bin, which decreases as we have fewer fitting options.
        let new_bin_cost = 45.0 + (fitting_bins_count as f64 * 1.5);
        new_bin_cost + completion_pressure
    } else {
        // Evaluate existing bins: prioritize Best-Fit (lowest post_residual)
        // while smoothing with the mean residual to encourage bin balance.
        post_res + gap_penalty + lookahead_penalty + (post_res - mean_residual).abs() * 0.2
    };

    base_score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
