                    score -= 10.0;
                }
            }
        }
    }

    // 3. Global state balance: discourage bins that are becoming too sparse compared to the mean.
    if !is_new_bin && (post_residual as f64 > mean_residual * 1.5) {
        score += 20.0;
    }

    // 4. Dynamic pressure: as we approach the end of the stream, prioritize packing tighter.
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for leaving space that is too small for common future items (Dead space avoidance)
    // We penalize based on the post_residual relative to the average bin state
    if post_res > 0.0 {
        let residual_efficiency = (post_res / mean_residual).powf(1.5);
        score += residual_efficiency * 10.0;
    }

    // Lookahead logic: if the next item is large, avoid splitting it by leaving too little space
    if next_item_size > 0 {
