    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. New Bin Thresholding: If this is an empty bin (bin_residual == bin_capacity),
    // we only want to pick it if the fitting_bins_count is 0 or if the current 
    // packing density is extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing options.
            score += 150.0 + (open_bins_count as f64 * 10.0);
        } else {
            // If no bins fit, this is mandatory.
            score -= 50.0;
        }
    }

    // 6. Progression Normalization: As we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
