    // Base score is the residual space (Best Fit logic).
    let mut score = post_residual as f64;

    // Apply penalties
    score += dead_space_penalty;
    score += lookahead_penalty;

    // Control pressure on opening new bins.
    // As the stream progresses, increase the cost of opening new bins.
    if is_new_bin {
        score += 25.0 + (progress * 20.0) + (open_bins_count as f64 * 2.0);
