    //    is extremely poor (suggesting we are fragmenting bins) or if no fit exists.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing options,
            // unless the existing options are very poor (mean_residual > 50).
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // Must open a new bin, neutralize the penalty.
            score = 0.0;
        }
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive
    //    in filling existing bins to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Avoid "Dead Zones": Penalize residuals that are too small to fit any expected 
    //    subsequent items (assuming items are typically >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but large enough to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the post_residual,
    // reward this bin choice.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let space_after_next = (post_residual - next_item_size) as f64;
            // Reward bins that leave space for the next item, penalize if it leaves an unusable sliver
            if space_after_next == 0.0 {
                score -= 40.0;
            } else if space_after_next < 10.0 {
                score += 20.0;
            }
        }
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0 + (open_bins_count as f64 * 5.0);
        } else {
            // If we MUST open a new bin, normalize the cost to keep it competitive
            score -= 10.0;
        }
    }

    // 4. Density Balancing: Favor bins that keep the mean residual closer to the item size,
    // preventing the creation of bins that are significantly "emptier" than the current average.
    let residual_delta = (post_residual as f64) - mean_residual;
    if residual_delta > 0.0 {
        score += residual_delta * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead zones": if the residual is too small to fit common items, penalize it.
    // We define a dead zone as space < 10 (the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If a next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong incentive: this bin can fit the next item perfectly.
            score -= 30.0;
            // Bonus for tight packing (minimizing wasted space between current and next).
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalty: this bin cannot fit the next item, forcing a new bin or a different choice.
            score += 15.0;
        }
    }

    // 3. Global efficiency: Balance against the mean residual to prevent fragmentation.
    // If our post_residual is significantly worse than the average, penalize it.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 4. Scarcity handling: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New bin management: If evaluating a new bin, apply a threshold based on progression.
    // As the stream nears completion, we become more aggressive in opening new bins to avoid forced bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Base cost of opening a new bin is 60.0, adjusted by progress and open bin count.
        score = 60.0 + (open_bins_count as f64 * 2.0) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
