pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic/Modulo logic: prioritize post_residuals that are multiples of common item sizes
    // Modulo 10 and 20 are common divisors for items in [10, 80]
    let waste_harmonic = (post_residual % 10) as f64 * 0.5;
    score += waste_harmonic;

    // 3. Lookahead logic: If next_item_size can fit into the post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
