    // 5. New bin penalty: Only open a new bin if the current fit is extremely poor
    if bin_residual == bin_capacity {
        // High penalty to open new bins; only choose if open bins are very full
        score = 60.0 + (mean_residual * 0.5);
    }

    // 6. Distribution adaptation: As we reach the end of the stream, prioritize clearing residuals
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
