    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
    }

    // Lookahead logic: if next item exists, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 5.0;  // Moderate penalty if next item won't fit
        }
    }

    // Global state optimization:
    // If this is a new bin (residual == capacity), penalize it based on how many 
    // existing bins could have fit the current item.
    if bin_residual == bin_capacity {
        // Only open new if we have very few options or if the current fill is poor
        score += (fitting_bins_count as f64) * 12.0;
        // Discourage opening too many bins early in the stream
        score += (open_bins_count as f64) * (1.0 - progress) * 5.0;
    } else {
        // Reward filling existing bins to improve packing density
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // If this bin is the last chance for this item, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Dynamic adjustment based on mean residual space
    // If the average bin is nearly full, be more conservative with new bins
    if mean_residual < 15.0 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

