    // Penalize small gaps (1-9) that are difficult to fill later, 
    // unless the item fits perfectly (post == 0).
    let mut score = if post == 0.0 {
        -50.0 // Reward perfect fits
    } else if post < 10.0 {
        30.0 + (10.0 - post) * 5.0 // Heavily penalize "near-miss" dead space
    } else {
        post
    };

    // Incorporate lookahead: if next_item_size fits in the remaining space, 
    // prioritize this bin to enable a tighter packing (Best Fit strategy).
    if next_item_size > 0 && next_item_size <= post_residual {
