    }

    // New bin penalty: If this is a new bin, apply a non-linear cost that 
    // increases with progress to force consolidation.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 60.0);
    }

    // Coupling with mean_residual: If this bin's residual is significantly 
    // higher than the mean, penalize it to encourage balancing.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
