    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: 
    // If post_residual is small but > 0, it creates a "sliver" (unusable space).
    // Penalize gaps smaller than the minimum possible item size (assumed ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy:
    // If we have a next item, check if it fits in the post_residual. 
    // Prioritize bins that perfectly accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it leaves a near-zero residual for the next item
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // 3. Open Bins Pressure:
    // Penalize opening new bins unless the current fit is extremely poor 
    // (high post_residual) or we have too many open bins already.
    if is_new_bin {
        // High penalty for opening a new bin if we have many fitting options
        score += (open_bins_count as f64 * 5.0) + (fitting_bins_count as f64 * 10.0);
    } else {
        // Encourage using existing bins that are already "fuller" than the mean
        if (bin_capacity - bin_residual) as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // 4. Progression weighting:
    // As we near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to prioritize tight packing.
    // 2. New-bin thresholding: If we are forced to open a new bin, make it expensive.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few options or the current fit is terrible.
        score = 25.0 + (fitting_bins_count as f64 * 5.0);
    } else {
        // 3. Lookahead Logic: Reward bins where the post_residual can fit the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect match/fit potential: significantly reduce the score.
                score -= 15.0;
                // Reward if the remaining space becomes exactly zero (perfect packing).
                if post_residual == next_item_size {
                    score -= 10.0;
                }
            } else {
                // If the next item won't fit, penalize based on how much "wasted" space we created.
                score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
            }
        }

        // 4. Mean Residual Balancing: Avoid starving bins that are already well-packed.
        // If this bin's post_residual is much lower than the mean, it is a "good" bin.
        if (post_residual as f64) < mean_residual {
            score -= 2.0;
        }

        // 5. Urgency: If this is the last chance to fit the item in an existing bin, favor it slightly.
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is "too empty" early on, 
    // but favor tight fits as the stream progresses.
    if bin_residual == bin_capacity {
        // Scoring the "New Bin" option:
        // Penalize opening a new bin heavily if we have plenty of open bins 
        // or if we are near the end of the stream.
        score = 85.0 + (open_bins_count as f64 * 2.0) + (progress * 50.0);
    } else {
        // Scoring an existing bin:
        // 1. Reward tighter fits (Best Fit principle).
        // 2. Penalty for creating small, unusable residuals (the "fragmentation" trap).
        if post_residual < 10 {
            score -= 15.0; // Highly desirable: very tight fit.
        } else if post_residual < 20 {
            score += 10.0; // Undesirable: leaves a small, hard-to-fill sliver.
        }

        // 3. Lookahead integration:
        // If the next item can fit in the current post_residual, reward this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // 4. Global state adjustment:
        // If this is the only bin that can fit the item, prioritize it to avoid 
        // unnecessary new bin openings.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 5. Dynamic balancing:
        // As the stream progresses, favor bins that align with the current mean_residual.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the square of the post_residual to heavily penalize large gaps (Best Fit principle).
    let mut score = post_res * post_res;

    // If this is a new bin, apply a progress-dependent penalty.
    // As the stream progresses, opening new bins becomes increasingly expensive.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64).powi(2) * (1.0 + progress * 2.0);
    } else {
        // If the bin is not new, reward placements that leave the bin residual 
        // close to the expected next item size to maximize packing density.
        if next_item_size > 0 {
            let diff = (post_res - next_item_size as f64).abs();
            score -= (bin_capacity as f64 - diff) * 0.5;
        }

        // Penalty for creating a bin that is too fragmented compared to the global mean.
        // This encourages filling bins that are already "denser" than average.
        if post_res < mean_residual {
            score -= (mean_residual - post_res) * 5.0;
        }

        // If this is the only bin that can fit the item, prioritize it to avoid 
        // wasting a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 500.0;
        }
    }

    // Apply a non-linear scaling factor based on the number of open bins to 
    // discourage excessive spreading.
    score += (open_bins_count as f64).powf(1.5) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic penalty: If post_residual is small but not zero, it is often "poisoned"
    //    space that cannot fit common items. We reward post_residual values that 
    //    are multiples of common item sizes or are zero.
    if post_residual > 0 {
        let harmonic_penalty = 15.0 / (1.0 + (post_residual % 20) as f64);
        score += harmonic_penalty;
    }

    // 3. Lookahead heuristic: If the next item fits into the current post_residual,
    //    heavily reward this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 4. Thresholding: If we are forced to open a new bin, penalize the new bin
    //    unless the mean residual of existing bins is already very low (high fragmentation).
    if bin_residual == bin_capacity {
        score += 30.0;
        if mean_residual < 15.0 {
            score += 20.0;
        }
    }

    // 5. Fitting constraints: If this is the only bin that can fit the current item,
    //    prioritize it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Progress-aware scaling: As we reach the end of the stream, prioritize
    //    closing bins (smaller residuals) over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "unusable" small gaps (dead space < 10, as items are >= 10).
    // If post_residual is in [1, 9], it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins if there are valid options.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of open bins is very low or no other bin fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 3. Lookahead heuristic: If the next item exists, reward bins that leave 
    // enough room to accommodate it (Best-Fit-like behavior).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item by reducing the score.
            score -= 15.0;
        } else if post_residual > 0 {
            // Penalize bins that block the next item from being placed in this bin.
            score += 5.0;
        }
    }

    // 4. Pressure management: If we have too many bins open, prioritize filling
    // existing bins with smaller residuals to consolidate space.
    if open_bins_count > 5 {
        // Favor bins that become very tight (residual approaching 0).
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // 5. Final adjustment based on mean_residual to avoid fragmentation.
    // If this bin's post_residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We penalize larger post_residuals exponentially to favor tight fits.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Matching (The "Perfect Fit" Reward):
    // If the post_residual exactly matches the next item, we reward it heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // 3. Fragmentation Avoidance:
    // If post_residual is too small to fit any common item (e.g., < 10), 
    // it is often "dead space". We penalize creating small slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 4. Mean Residual Balancing:
    // If we are significantly above the mean residual, we are creating a "loose" bin.
    // Penalize placements that increase the bin's residual relative to the global mean.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 2.0;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), we add a high cost 
    // to discourage opening new bins unless the fit in existing bins is terrible.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Discount the new bin cost if we are running out of options.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // 6. Progress Scaling:
    // As we near the end of the sequence, prioritize finishing existing bins (lower score).
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
