pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on current average density
    // We want to avoid opening a new bin unless the existing ones are very full.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64 - mean_residual) * 2.5;
        score += (open_bins_count as f64) * 0.5;
    } else {
        // 2. Harmonic/Best-Fit logic:
        // Penalize small post_residuals that are "unusable" (e.g., < 10)
        // unless they are exactly 0 (perfect fit).
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; 
        }

        // 3. Lookahead integration:
        // If the next item could fit into this post_residual, reward this bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.2;
