        // 4. Fitting constraints:
        // If this is the only bin that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // 5. Progress-based scaling:
        // As the stream progresses, become more aggressive about filling bins
        // to minimize the number of open bins near the end.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 6. Modulo-based "Bin Packing Class" penalty:
    // Favor bins that result in a post_residual that is a multiple of 20
    // (creating larger empty chunks for future large items).
    if post_residual % 20 == 0 {
