    // As post_residual approaches 0, the penalty increases, 
    // but we favor tighter fits (smaller post_residual) generally.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powf(1.5)
    } else {
        0.0
    };

    // Factor in the lookahead: if the next item is large, 
    // we want to preserve space in the current bin if possible.
    let next_item_impact = if next_item_size > 0 {
