        }
    } else {
        0.0
    };

    // Dynamic thresholding: as we near the end of the stream, 
    // become more aggressive about filling bins (Best Fit).
    let progress_weight = 1.0 + (progress * 2.0);

    // Base score is the residual space. We want to minimize this.
    // We adjust the base score by the fragmentation penalty and the lookahead.
    let mut score = (post * progress_weight) + fragmentation_penalty + next_item_impact;

    // If this is the last chance for this item, reduce the penalty for opening a new bin
    // by making existing bins slightly less attractive if they result in poor fits.
    if fitting_bins_count == 1 && post > 20.0 {
        score += 10.0;
    }

    // New bin candidate handling:
    // If bin_residual == bin_capacity, this is a new bin.
    // We penalize opening a new bin heavily unless the current open bins 
    // are all very poor fits (high residuals).
    if bin_residual == bin_capacity {
        score = 40.0 + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

