        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Heavily reward perfect tight fits for the next item
            score -= (100.0 - gap as f64) * 0.8;
        }

        // Penalize creating "fragmented" bins that are worse than the current mean
        if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
            score += 20.0; // Penalty for creating small, unusable slivers
        }

        // If this is the last chance for this item (only one bin fits), prioritize it
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Dynamic pressure: as we approach the end of the stream, prioritize filling gaps
        score -= (progress * 20.0);

        score
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger residuals after placement.
    // This naturally favors filling bins as tightly as possible.
    score += post_residual as f64 * 1.2;

    // 2. Lookahead mechanism: 
    // If the next item is large, we want to leave enough room for it.
    // If next_item_size cannot fit in the post_residual, we penalize this bin
    // unless it's the only option or the bin becomes perfectly full (0 residual).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            // Penalty for stranding the next item if it's large
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        } else {
            // Reward bins that can accommodate the next item perfectly
            score -= (bin_capacity as f64 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // 3. Dynamic Thresholding:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;

    // 4. Handling New Bin Candidate:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is scaled by how many bins are already open
        // and how much room is left in existing bins.
        let efficiency_penalty = (open_bins_count as f64 * 5.0) + (mean_residual * 0.2);
        score += 25.0 + efficiency_penalty - (progress * 10.0);
    } else {
        // 5. Prefer bins that are already "half-full" to keep the number of active bins low.
        // If fitting_bins_count is 1, this is the only bin that can take the item, 
        // so we heavily discount the score to ensure it is chosen.
        if fitting_bins_count == 1 {
            score -= 50.0;
        }

        // Penalize bins that are very empty (high residual) to force consolidation
        score += (bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" (very small residuals that are hard to fill).
    // We penalize residuals between 1 and 9 (inclusive) as they are statistically 
    // unlikely to accommodate the average item distribution.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: If next_item_size is large, we want to preserve larger 
    // residuals in existing bins. If next_item_size is small, we are more 
    // permissive of tight fits.
    if next_item_size > 0 {
        let diff = (next_item_size as f64 - post).abs();
        score += diff * 0.5;
    }

    // Progress-based scaling: As the stream nears completion (progress -> 1.0), 
    // we become significantly more aggressive about filling existing bins to 
    // avoid opening new ones.
    if bin_residual == bin_capacity {
        // New bin penalty increases as the stream progresses to discourage 
        // opening new bins late in the process.
        score += 40.0 + (progress * 60.0);
    }

    // Balance the usage of bins: If we have many open bins, we penalize 
    // residuals that deviate significantly from the current mean_residual.
    if open_bins_count > 1 {
        score += (post - mean_residual).abs() * 0.2;
    }

    // Criticality: If this is the only bin that can fit the item, 
    // we lower the score to force the selection of this bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (post_residual < 10) that are rarely useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Class Logic: penalize residuals that cannot fit common item sizes
    // If post_residual is a "bad" remainder, increase score.
    let remainder = post_residual % 20;
    if remainder > 0 && remainder < 5 {
        score += 15.0;
    }

    // 3. Lookahead integration: Try to leave room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
