    // 4. Pressure management: If we have many open bins, prioritize closing them (Best Fit)
    // If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. New Bin logic: Only open if we really have to
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is high, but scales with how many bins are already open
        score += 40.0 + (open_bins_count as f64 * 0.5);
    }

    // 6. Global progress adjustment: As we reach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit common items
