    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Mean Residual Balancing:
    // Favor bins that keep the overall mean residual consistent.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
