    // 5. Progression Scaling:
    // Towards the end of the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (the "Best-Fit" logic)
    // We want to minimize post_residual, but avoid creating "dead space" that is too small for common items.
    // If post_residual is in the "danger zone" (1..9), penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
