    // 3. New Bin Thresholding: Prevent opening a new bin unless the existing fits are very poor.
    // If we are considering a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless the number of open bins is very low or the item size is very large.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many bins open, discourage opening more.
        score += (open_bins_count as f64) * 2.0;
    }

    // 4. Global State Awareness: If we are near the end of the stream, be more aggressive
    // about packing tightly to avoid straggler bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 5. Fitting Context: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Mean Residual Coupling: Encourage balancing residuals across bins.
    // If this bin's residual is significantly lower than the mean, it's a good candidate.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
