    score -= (1.0 - progress) * (bin_capacity - post_residual) as f64 * 0.1;

    // Favor bins that have residuals closer to the mean_residual to keep bin distribution uniform.
    let residual_diff = (post as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // High penalty for creating 'useless' space (e.g., residual < 10) unless it's the last item.
    if post_residual < 10 && post_residual > 0 && next_item_size > 0 {
