    // Combine: Minimize post_residual (Best Fit), but adjust for fragmentation and lookahead
    let mut score = post + dead_space_penalty + new_bin_bias + lookahead_weight;

    // Favor bins that are closer to the mean usage to keep bin levels balanced
    let usage_deviation = (bin_capacity - bin_residual) as f64 - (bin_capacity as f64 - mean_residual);
    score += usage_deviation.abs() * 0.1;

