    // 2. Lookahead Synergy: If the next item can fit in the remaining space (post_residual),
    // we reward this placement to keep the current bin useful for the immediate future.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // 3. Open Bin Pressure: As the stream progresses, we want to consolidate items 
    // into existing bins to avoid opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 + progress * 2.0);

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // reduce the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Bias: If evaluating a new bin (bin_residual == bin_capacity), 
    // apply a base cost that increases with the number of open bins to discourage 
    // fragmenting the packing unnecessarily.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
