    // 4. Global balance: Prefer bins that stay close to the mean residual of the system,
    // preventing the creation of extreme outliers.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progress scaling: As the stream nears the end, prioritize finishing off bins (packing tighter).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
