        score -= 40.0;
    }

    // Dynamic thresholding: as the stream progresses, we become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), increase the cost to open it.
    if bin_residual == bin_capacity {
        let open_bin_penalty = 30.0 + (progress * 50.0);
        score += open_bin_penalty;
    }

    // Coupling with fitting_bins_count: If this is the only bin that fits the item, 
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Interaction with mean_residual: If current bin is significantly worse than the average,
    // penalize it to encourage balancing the load.
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // post_residual: smaller is better (Best Fit).
    // post_residual == 0: Perfect fit, highest priority.

    let mut score = post_residual as f64;

    // 1. Encourage perfect fits (Best Fit Decreasing logic)
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead: If next_item_size fits in the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Reward residual space that is a multiple of the next item size (harmonic alignment)
        score -= (post_residual % next_item_size) as f64 * 0.5;
    }

    // 3. Penalty for "New Bin" creation (bin_residual == bin_capacity)
    // Only open a new bin if the current fit quality is very poor (e.g., leaving > 40 space).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if existing bins can take the item
            score += 60.0;
        } else {
            // If no bins fit, this is mandatory; set a neutral/low score
            score += 10.0;
        }
    }

    // 4. Harmonic thresholding: Penalize residuals that are too small to fit common items (10-20)
    // but large enough to create fragmentation.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 5. Global state normalization:
    // As the stream progresses, prioritize closing bins to keep the number of active bins stable.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64 * progress) * 2.0;

    // 6. Mean residual bias: Avoid bins that deviate significantly from the average empty space
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is small but > 0, it's often unusable.
    // We penalize values < 10 (common lower bound for item sizes) to force tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
