    // 3. Open bins pressure: As we progress, penalize opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), add a cost based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Encourage using existing bins that are already "half-empty" to keep mean_residual balanced.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // 4. Progress dependency: Towards the end of the stream, be more conservative with bin openings.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (tiny residuals that are unlikely to fit future items)
    // We target residuals that are either 0 or large enough for the average future item.
    if post_residual > 0 && post_residual < 15 {
