    }

    // 2. Lookahead logic: If this placement makes it impossible to fit the next item, 
    // but another bin might, penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize closing off the next item, but weight it by how many alternatives exist
            score += 30.0 / (fitting_bins_count as f64 + 0.1);
