    }

    // 3. New bin handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are all very tight
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 50.0;
        } else {
            score += 65.0;
        }
    }

    // 4. Prefer bins that are already closer to the mean residual to maintain packing density
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Progression scaling: Be more conservative with new bins as we approach the end
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a "sliver" (fragmented space too small for most items)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Heuristic: If we have a lookahead item, prioritize bins that can accommodate BOTH
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that are perfectly sized for the current + next item
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.2;
        } else {
            // Penalize bins that block the next item from fitting, scaled by progress
            score += 15.0 * (1.0 - progress);
        }
    }

    // Global state awareness: If we have many open bins, penalize opening a new one
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High cost to open a new bin if we have plenty of open bins
        score += (open_bins_count as f64 * 2.5);
    } else {
        // Reward bins that stay close to the global mean residual to keep packing uniform
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;
    }

    // If this is the last chance to fit an item into an existing bin, favor it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Dynamic threshold: As we near the end of the stream, prioritize tightest fit (Best Fit)
    // to minimize wasted capacity in the final bins.
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) increasingly as the stream progresses.
    // This forces the algorithm to exhaust open bins towards the end of the stream.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        100.0 * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Calculate a "Best Fit" baseline: lower post_residual is better.
    // We exponentiate post_residual to heavily penalize large gaps.
    let fit_score = (post * post) / 100.0;

    // Lookahead coupling: if the next item is large, favor bins that leave enough space
    // for it, or conversely, if the current bin becomes too tight, penalize it.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Diversity / Load balancing: favor bins that keep the mean residual balanced.
    // If a bin's post_residual is far from the mean_residual, it is less "stable".
    let stability_score = (post - mean_residual).abs() * 0.5;

    // Criticality: If this is the only bin that fits, we must prioritize it unless
    // the penalty for creating a new bin is lower than the current post_residual.
    let criticality_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    fit_score + new_bin_penalty + lookahead_penalty + stability_score + criticality_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Base score is the post_residual (Best Fit logic).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that are hard to fill).
    // Specifically, residuals < 10 are often unusable for the given item range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Strong reward for keeping a bin "next-item compatible".
            score -= 25.0;
        } else {
            // Penalty for stranding the next item if this bin was the only option.
            score += 15.0;
        }
    }

    // 3. New Bin Thresholding:
    // If we are looking at a new empty bin (bin_residual == bin_capacity),
    // only pick it if the mean_residual of existing bins is already tight (< 15).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 15.0 {
            // Penalize opening a new bin if we have plenty of space elsewhere.
            score += 60.0;
        } else {
            // Otherwise, keep the score neutral/low to allow new bin creation.
            score += 20.0;
        }
    }

    // 4. Fitting Density: 
    // If this is the last fitting bin (fitting_bins_count == 1), we should prioritize 
    // using it rather than opening a new bin, unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // 5. Progression scaling:
    // As we approach the end of the stream, prioritize closing bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
