    // Base score is the post_residual (Best Fit principle).
    // We penalize small residuals that are likely to become "dead space" (e.g., < 10 units).
    let mut score = post;
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - (post / 10.0));
    }

    // Heuristic: Prefer bins that leave space for the lookahead item.
    // If next_item_size exists, we penalize bins that cannot fit it, 
    // but only if we have other options.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        } else {
            // Reward bins that can accommodate the next item perfectly.
            score -= 5.0 * (1.0 - (post - next_item_size as f64) / 100.0);
        }
    }

    // Dynamic constraint: As the stream progresses, become increasingly conservative
    // about opening new bins by penalizing the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress and the number of currently open bins.
        score += 40.0 * progress + (open_bins_count as f64 * 0.5);
    }

    // Encourage density by penalizing bins that deviate significantly from the mean_residual.
    // This helps keep the bin fill levels uniform.
    let residual_diff = (post - mean_residual).abs();
    score += 0.2 * residual_diff;

    // Favor bins that are "last chance" to prevent premature new bin opening
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
