    // If the post_residual is small but not zero, it's often a "wasted" sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64 + 0.1);
    }

    // 2. Harmonic Lookahead: If next item fits in the current post_residual, reward this bin.
    // This is a greedy approach to minimize the number of bins by packing pairs.
