    // This keeps the remaining space distribution uniform, allowing for future flexibility.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Logic: If we are considering a new bin (bin_residual == bin_capacity), 
