        if mean_residual < 15.0 {
            score += 20.0;
        }
    }

    // 6. Progress weighting: As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 100.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range (0, 10), it is highly likely 
    // to become unusable "fragmentation" since min item size is typically > 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Best-Fit Bias: Penalize leaving large residuals.
    score += (post_residual as f64) * 0.5;

    // 3. Lookahead Sensitivity: If the next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Global Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless necessary, by scaling the score based on existing open bin count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Fragmentation Awareness: If this is the last fitting bin, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Efficiency Normalization: Favor bins that align with the current mean residual 
    // to keep bin utilization balanced across the set.
    let residual_delta = (post_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // Start with the post_residual (the space left after placement).
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10, since min item size is 10).
    // If post_residual is 1..9, it is effectively useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size can fit into the post_residual,
    // we heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Prefer bins that are already closer to the mean residual (balancing).
    // This reduces variance in bin fullness.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 4. Handle the "New Bin" case:
    // If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if the current fit is very poor (high post_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin to prevent fragmentation.
        // We only open if the current open bins are all very poor fits.
        score += 45.0; 
    }

    // 5. Criticality adjustment:
    // If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progress-based refinement:
    // As we approach the end of the stream, prioritize tighter fits.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that result in smaller post_residual (tighter fit).
    // The base score (post_residual) already incentivizes this.

    // 2. Penalize creating "dead space" (residuals too small to fit common items).
    // If post_residual is < 10, it is likely unusable for future items (range 10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization: If next_item_size is large, avoid leaving a small residual.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // 4. Global state adjustment: If many bins are open, be more aggressive to pack tightly.
    // Penalize new bins if we already have many open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have fitting bins, heavily penalize opening a new one unless the fit is terrible.
        if fitting_bins_count > 0 {
