        }
    }

    // 5. Dynamic time horizon: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Near end, prioritize fitting into existing bins to avoid adding new ones.
        if bin_residual == bin_capacity {
            score += 100.0;
        }
    }

    // 6. Balance the mean residual: If this bin's post_residual is much worse than the mean, penalize.
    if (post_residual as f64) > mean_residual + 10.0 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers" (very small unusable gaps)
    // We penalize post_residuals that are too small to fit common items (e.g., < 10)
    if post_res > 0.0 && post_res < 10.0 {
        score += 20.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the current choice
    // to preserve capacity for the upcoming item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 15.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Dynamic adjustment based on stream progress. 
    // As we near the end of the stream, we become more aggressive in packing
    // tightly to avoid opening new bins.
    let tightness_factor = 50.0 * (1.0 - progress);
    score += (mean_residual - post_res) * tightness_factor;

    // Favor bins that are already open (penalty for opening new bins)
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open a new bin if the fitting_bins_count is low, 
        // or if the average residual of existing bins is already very poor.
        let open_penalty = 25.0 + (open_bins_count as f64 * 0.5);
        score += open_penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a 'sliver' (unusable space < 10, as items are >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item can fit in the post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // Encourage filling bins that are already closer to capacity (Best-Fit principle)
    // We want the post_residual to be small, so this is naturally aligned.
    // However, we apply a penalty for creating a new bin if we have fitting bins available.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if others exist
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Baseline cost for mandatory new bin
            score += 20.0;
        }
    }

    // Harmonic class logic: penalize post_residuals that are "inconvenient" for common item sizes
    // Items are 10-80, so common sums are multiples of 10 or 20.
    let remainder = post_residual % 10;
    if remainder != 0 {
        score += remainder as f64 * 0.5;
    }

    // Progression weight: as we near the end of the stream, prioritize packing tighter
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
