    // proportional to the progress, as we want to pack tighter toward the end.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Best-Fit Decreasing logic: reward small post_residuals.
    // We apply a non-linear scaling to post_residual to prioritize tight fits.
    let fit_score = post_res.powf(1.5);

