    // Diversity penalty: discourage spreading items across too many bins early on.
    let dispersion_penalty = (open_bins_count as f64) * 2.0 * (1.0 - progress);

    // Combine factors. Lower score is better.
    let score = fit_score + new_bin_penalty + next_fit_penalty + dispersion_penalty;

