    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes
    // Modulo 20 and 25 are strong clusters for bin packing (100 / 4 and 100 / 5)
    let harmonic_penalty = ((post_residual % 20) as f64 * 0.5) + ((post_residual % 25) as f64 * 0.3);
