    }

    // Handle the "New Bin" candidate (where bin_residual == bin_capacity).
    // We only want to open a new bin if the current open bins are very "bad" fits
    // or if we have many items left and need to preserve space for future combinations.
    if bin_residual == bin_capacity {
        // High base penalty for opening a new bin.
        score = 65.0 + (progress * 10.0);

        // If we have many open bins that are already quite full, don't open a new one.
        if mean_residual < 20.0 {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" (very small residuals that cannot fit common items)
    // We define a non-linear penalty for residuals in the (0, 10) range.
    let dead_space_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Reward bins that have residuals close to the mean, promoting balanced bin filling.
    let balance_reward = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size is large, avoid bins that leave a tight residual.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size - post_residual) as f64 * 2.0
    } else {
        0.0
    };

    // Strategic progression: As we approach the end of the stream, be more aggressive
    // about filling existing bins (minimizing post_residual) to avoid opening new ones.
    let stream_pressure = (1.0 - progress) * post_res;

    // Final score calculation: 
    // Lower score is better. We add penalties and subtract rewards.
    let mut score = post_res + dead_space_penalty + lookahead_penalty + balance_reward + stream_pressure;

    // If this is a new bin (bin_residual == bin_capacity), add a significant cost
    // to discourage opening new bins unless the existing ones are extremely poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + (progress * 20.0);
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // strongly favor this bin to avoid an unnecessary new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a small, unusable gap (fragmentation)
    // We penalize residuals that are too small to fit common items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Lookahead logic: if we know the next item, try to leave space for it
    // If the current placement leaves a gap that perfectly fits the next item, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit or near-fit for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 / (1.0 + diff));
        }
    }

    // Harmonic class logic: Favor bins that align with large item groupings
    // We use modulo to identify bins that are "clean" (e.g., leaving 0, 20, 25, 33, 50)
    let remainder_score = (post_residual % 20) as f64;
    score += remainder_score * 0.5;

    // Global state awareness:
    // If we have many open bins, penalize opening a new one heavily.
    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate score
        // Only choose this if all other bins are terrible fits
        score += 25.0 + (open_bins_count as f64 * 2.0);
    } else {
        // If it's a tight fit (post_residual is small), prioritize this bin
        if post_residual < 15 {
            score -= 15.0;
        }

        // If this is the only bin that fits, prioritize it
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Progression awareness: Towards the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely "unusable" 
    // for future items (sizes 10-100). We penalize this heavily to favor tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Integration: If the next item cannot fit into this post_residual,
    // we penalize this bin slightly more to encourage placing items in bins that 
    // can accommodate the next item (Best-Fit-Lookahead variant).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bin Pressure: As the stream progresses, we want to consolidate.
    // If this is a new bin (bin_residual == bin_capacity), we add a penalty that 
    // scales with the number of bins already open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 1.5);
    }

    // 4. Fitting Scarcity: If this is the last bin that can fit the item, 
    // we prioritize it heavily to avoid opening a new unnecessary bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Mean residual alignment: Favor bins that keep the overall mean residual 
    // consistent with the current bin's residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

