    // If post_residual is < 10, it is likely "dead space" because min item size is usually > 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Matching: Reward bins where the post_residual matches the next_item_size.
    // This effectively implements a Best-Fit-Decreasing style logic for the pair.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += diff * 0.5;
    }

    // 3. Global Bin Management: Penalize opening a new bin unless the existing options are very poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only consider a new bin if the mean residual of current bins is already quite low,
        // or if we have very few bins open (high flexibility).
        score += 35.0 - (open_bins_count as f64 * 0.2);
    }

    // 4. Fitting Pressure: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 5. Mean Residual Balancing: Prefer bins closer to the global average residual to keep
    // bin levels consistent, preventing the accumulation of "outlier" bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    // 6. Progress Scaling: As the stream nears completion, prioritize closing open bins
    // by favoring those that are already near capacity.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
