        // Further reward if it leaves a very tight remaining space
        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 3. New Bin Thresholding: Prevent opening a new bin unless existing bins are very poor
    if bin_residual == bin_capacity {
        // High barrier to opening a new bin
        score += 35.0;
        // If there are many open bins that can fit the item, opening a new one is very bad
        score += (fitting_bins_count as f64) * 10.0;
    }

    // 4. Global Balance: If the current bin's residual is significantly worse than the 
    // global mean_residual, penalize the placement to encourage usage of fuller bins.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Urgency: As we approach the end of the stream, prioritize closing bins
    // to avoid leaving too many partially filled bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle).
    // We favor bins where the remaining space is small, but penalize tiny "sliver" residuals
    // that are too small to fit any likely future items (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead Coupling: If a future item is known, prioritize bins that can 
    // fit both the current and the next item (synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // If the current bin cannot fit the lookahead, penalize it slightly 
            // to favor bins that can maintain a multi-item chain.
            score += 15.0;
        }
    }

    // 3. Global State Balancing: Use mean_residual to prevent "bin-starvation".
    // If the current bin is significantly emptier than the average, it's a "cold" bin.
    // We prefer filling existing bins over opening new ones unless the bin is very empty.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost is high.
        score += 55.0;
        // Reduce penalty if current bins are already very full (mean_residual is low).
        score -= (mean_residual * 0.5);
    } else {
        // Reward filling existing bins that are close to the mean.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. Last Chance Heuristic: If this is the only bin that fits, take it 
    // regardless of the residual quality to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating a bin with very small, unusable space (fragmentation).
    // If post_res is small but > 0, it is often a "dead" space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Dynamic Lookahead: If next_item_size is large, avoid bins that leave too little space.
    // We penalize bins where the post_residual is less than the next item size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - (post_res / next_item_size as f64));
    }

    // Progress-based scaling: As the stream progresses, prioritize closing bins (lower residual)
    // to prevent straggler bins at the end.
    score += (1.0 - progress) * (post_res * 0.5);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless it is the only option (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one could fit the item.
            score += 60.0 + (mean_residual * 0.5);
        } else {
            // If we must open a new bin, normalize the cost.
            score = 40.0;
        }
    }

    // Favor bins that align with the mean density of the current set.
    score += (post_res - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    // 2. Harmonic/Modulo logic: Favor residuals that are multiples of common item sizes
    // Modulo 10, 20, 25 are common "perfect" boundaries for 100 capacity
    let residual_penalty = (post_residual % 10) as f64 * 2.5;
    score += residual_penalty;

    // 3. Lookahead logic: If the next item fits into the current post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
        // Further reward if it leaves a "clean" remainder for a potential third item
        if post_residual - next_item_size >= 20 {
            score -= 20.0;
        }
    }

    // 4. Threshold Logic: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin logic: Only open a new bin if the current fit is "too tight" (under 10 units left)
    // or if we are at the very start of the process
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin unless the existing fitting bins are very poor
            score = 60.0 + (mean_residual * 0.5);
        }
    }

    // 6. Progression scaling: As we approach the end, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is in the range (0, 10), it is highly likely to become
    // unusable "fragmentation" since items are >= 10. Penalize this heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead optimization: If the next item fits in the current post_residual, 
    // reward this placement to keep bins compact.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open bins pressure: If this is an existing bin (not a new one), 
    // favor bins that are already "fuller" to minimize total open bin count.
    if bin_residual < bin_capacity {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 4. Strategic new-bin threshold: Only open a new bin if the current fit is terrible.
    // If we have many open bins, penalize opening a new one.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
        // If we have many fitting bins, it is almost never optimal to open a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 5. Global state adjustment: As we approach the end of the stream, 
    // prioritize packing tighter to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the remaining capacity (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 25.0;
        // If there are other bins that could fit this, heavily penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Lookahead logic: Reward bins where the post_residual can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (20.0 - fit_diff).max(0.0);
        } else {
            // Penalize creating a bin that will definitely require a new bin for the next item
            // unless the current post_residual is already very small (dead space)
            if post_residual > 5 {
                score += 10.0;
            }
        }
    }

    // Heuristic: Prefer bins that stay close to the current mean residual
    // This helps in keeping the bin usage density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Final adjustment: Penalize leaving extremely small, unusable gaps (1-4)
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

