    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // 5. Balance residuals: If current bin is much emptier than the average open bin, 
    // it is a good candidate to fill up.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.2;
    }

    // 6. Non-linear penalty for "dead space" creation (residuals too small for common items)
    // If post_residual is < 10, it's effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily in early stages, 
    // but increasingly allow it if the fitting bin is poor (Best Fit style).
    let is_new_bin = bin_residual == bin_capacity;

    // Non-linear coupling: 
    // We prioritize bins that result in a "tight" post-residual.
    // We penalize larger post_residuals quadratically.
    let mut score = post * post * 0.01;

    // If the bin is new, apply a dynamic cost based on progress and current open bins.
    if is_new_bin {
        // As the stream progresses, the penalty for opening a new bin decreases 
        // if the current open bins are already quite full (mean_residual is low).
        score += (bin_capacity as f64) * (1.0 - progress) * (1.0 + (mean_residual / bin_capacity as f64));
    } else {
        // If the bin is already open, favor it more if it's the only one that fits the current item.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Lookahead heuristic: If the next item exists, penalize bins that leave too little 
        // space for the next item, or reward bins that leave exactly enough.
        if next_item_size > 0 {
            if post >= next_item_size as f64 {
                // Reward bins that can accommodate the next item perfectly.
                score -= (post - next_item_size as f64).exp() * 0.1;
            } else {
                // Penalize bins that leave "stranded" space too small for the next item.
                score += (next_item_size as f64 - post) * 0.5;
            }
        }
    }

    // Influence of total open bins: discourage fragmentation.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

