    // 4. Thresholding:
    // If this is the only bin that fits the item, make it very attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. New Bin Management:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Only open a new bin if the mean_residual of existing bins is already very low,
    // indicating that existing bins are too full to accommodate future variance.
    if bin_residual == bin_capacity {
        if mean_residual > 30.0 {
            score -= 10.0; // Willing to open a new bin if existing bins are sparse.
        } else {
            score += 200.0; // Strongly discourage opening new bins if existing are tight.
        }
    }

    // 6. Progress Scaling:
    // As the stream progresses, prioritize closing bins (packing tighter).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

