    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Mean residual equilibrium: Avoid bins that deviate significantly from the mean
    // to encourage uniform packing.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
