pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (gaps < 10 are generally unusable given item range 10-100)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Penalize opening new bins when space is available, but reward new bins if current fit is very poor
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current mean residual is already quite tight
        if mean_residual > 20.0 && open_bins_count > 0 {
            score += 40.0;
        } else {
            score += 100.0;
        }
    }

    // 3. Lookahead Logic: If the next item is large, avoid leaving small residuals
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= 10 {
            // High penalty if this placement makes it impossible to fit the next item
            score += 30.0;
        }
    }

    // 4. Pressure: If many bins are open, prioritize filling existing bins to consolidate
    score += (open_bins_count as f64) * 0.5;

    // 5. If this is the only bin that fits the current item, prioritize it strongly to avoid unnecessary new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 6. Prefer bins that are already "half-full" to maintain packing density
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" (residuals too small for common items, but too large to be efficient)
    // Small residuals are only good if they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead optimization: If current bin can fit the next item, prioritize it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Prevent premature new bin opening: If this is an empty bin, penalize it heavily 
    // unless no other bin can fit the current item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0; // Accept new bin only if necessary
        }
    }

    // 4. Balance current bin with the global state: 
    // If the bin is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Prefer tight fits (Best Fit heuristic)
    score += post_residual as f64 * 0.1;

    // 6. Dynamic pressure: As the stream progresses, increase pressure to close bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Penalize creating "dead zones" (residuals < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead logic: if next_item_size fits in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Dynamic balance: Reward filling bins that are already closer to the mean_residual
    // to keep bin utilization variance low, but shift strategy as we approach the end of the stream.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * (0.5 * (1.0 - progress));

    // 4. New Bin Logic: Discourage opening new bins unless it's the only option or the fit is excellent.
    if is_new_bin {
        // If we have many open bins that fit, opening a new one is highly undesirable.
        if fitting_bins_count > 0 {
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no other bin fits, this is mandatory.
            score -= 10.0;
        }
    } else {
        // 5. Encourage Best-Fit behavior: punish large remaining residuals.
        score += (post_residual as f64) * 0.2;
    }

    // 6. End-game urgency: As the stream ends, be more aggressive with packing.
    if progress > 0.9 {
        score -= (100 - post_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: increases as we progress through the stream
    // to encourage density early and conservation late.
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    }

    // Quadratic penalty for creating small "sliver" residuals (dead space)
    // We penalize residuals that are too small to fit common items (e.g., < 15)
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64).powi(2) * 0.5;
    }

    // Lookahead coupling: if the next item is large and won't fit the post_residual,
    // we penalize this placement to keep the bin open for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * (1.0 - progress);
    }

    // Global density pressure: if the mean residual is high, we are being too wasteful.
    // Discourage opening new bins if we already have many bins with large residuals.
    if is_new_bin && mean_residual > 20.0 {
        score += mean_residual * 0.8;
    }

    // Fitting constraint: if this is the last bin that can fit the item,
    // strongly reward using it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead Space" avoidance)
    // We penalize post_residuals that are too small to fit the most likely remaining items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly or efficiently fit the next item
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize bins that block the next item from fitting
            score += 10.0;
        }
    }

    // 3. Density Management: Penalize creating a new bin unless necessary
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are already too crowded (high mean_residual is better)
        // We normalize the penalty for opening a new bin based on the progress of the stream
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * (1.0 - progress);

        // If we have many open bins that could have fit this item, penalize opening a new one heavily
        score += (fitting_bins_count as f64) * 20.0;
    }

    // 4. Residual Balancing: Prefer bins closer to the mean residual to keep distribution uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_diff;

    // 5. Harmonic Class Logic: Favor filling bins to specific thresholds (e.g., 50, 75, 90)
    // This encourages "tight" packing by rewarding bins that reach high utilization fractions
    let utilization = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if utilization > 0.8 {
        score -= 10.0;
    }
    if utilization > 0.95 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but not zero (which is perfect). A residual between 1 and 9 is often "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bin Pressure: If we have many open bins, prioritize filling them to consolidate.
    // Scale penalty by current open bin count to prevent unnecessary fragmentation.
    score += (open_bins_count as f64) * 2.5;

    // 3. Lookahead Sensitivity: If the next item is large, avoid leaving a small residual that prevents it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0;
    }

    // 4. Fitting Constraint: If this is the last chance to fit the item in an existing bin,
    // reward it heavily to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. New Bin Penalty: Make opening a new bin (bin_residual == bin_capacity) expensive 
    // unless the fit in existing bins is truly abysmal.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Mean Residual Balancing: Penalize bins that deviate significantly from the mean,
    // encouraging a uniform "filling" strategy.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We already start with post_residual, so we apply modifiers.

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, reward it.
    // Specifically, if post_residual is slightly larger than next_item_size, we create a perfect pack.
    if next_item_size > 0 {
