    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    // 5. New Bin Threshold: Discourage opening a new bin unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we are forced or the mean residual 
