    }

    // 3. Prevent fragmentation: if the residual is small but unusable, penalize it
    // Small residuals like 1-9 are often "dead space" unless they perfectly match an item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 4. Harmonic thresholding: Favor bins that leave space divisible by common item sizes
    // If post_residual is a multiple of 20, it's a "clean" remainder.
    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 5. New Bin logic: Only open a new bin if the current fit is terrible
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already, or the item is huge (bad fit for others)
        if open_bins_count > 0 {
            score += 40.0; // Penalize creating new bins unless necessary
        }
        if item_size > 70 {
            score -= 20.0; // Prefer new bin for large items to save room in existing bins
        }
    }

    // 6. Progressive scaling: As we approach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 7. Fitting bins constraint: If this is the only bin that fits the item, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
