    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active,
    // but reward using existing bins to keep the count low.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin increases with the number of already open bins.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // Reward using an existing bin to consolidate.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Fitting Count Utility: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 5. Mean residual equilibrium: Favor bins that keep the overall mean residual stable
    // to prevent fragmentation across multiple bins.
    let residual_delta = (post_residual as f64) - mean_residual;
    score += residual_delta.abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Lower post_residual is generally better.
    // However, we penalize very tight fits that might orphan the bin (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 2. Lookahead matching: If next_item_size fits in the remaining space, 
    // prioritize this bin heavily to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. New Bin Penalty: If this is a new bin, penalize it unless the 
    // current bin_residual is exactly bin_capacity.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the existing options are very poor (high post_residual)
            score += 45.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly 
    // worse than the average current state.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Progression awareness: As we approach the end of the stream, 
    // become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 && bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best Fit Decreasing logic: heavily favor bins with low post_residual
    // 2. Penalty for creating "dead space": if post_residual is in (0, 10), it's likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
    }

    // 3. Lookahead integration: if a future item fits perfectly in the remaining space, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (25.0 / (1.0 + diff));
    }

    // 4. Dynamic threshold for opening new bins: 
    // Discourage new bins unless necessary, but become more lenient as the stream progresses.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty for opening a new bin if an existing one is available.
            // Scale this penalty inversely with progress to allow more "packing room" at the end.
            score += 65.0 * (1.0 - progress * 0.5);
        } else {
            // No choice, must open new bin.
            score = 0.0;
        }
    }

    // 5. Global state coupling:
    // If the mean residual of open bins is high, prefer bins that bring us closer to the mean.
    // This helps keep bins balanced in their remaining capacity.
    let residual_delta = (bin_residual as f64 - mean_residual).abs();
    score += residual_delta * 0.1;

    // 6. Final constraint: ensure we don't favor bins that can't fit the item.
    if bin_residual < item_size {
        score = 1e9;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for leaving small "dead space" (e.g., 1-9) that is hard to fill later.
    // We use a non-linear exponential penalty that peaks when post_res is small but non-zero.
    if post_res > 0.0 {
        score += 15.0 * (-0.2 * post_res).exp();
    }

    // Adaptivity: If we are late in the stream, prioritize filling existing bins aggressively.
    // Penalize opening new bins (bin_residual == bin_capacity) more as progress increases.
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    }

    // Lookahead coupling: If the next item is large, favor bins that leave enough space
    // to accommodate it, or conversely, finish off a bin if it's too small for the next item.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post_res < next_item && post_res > 0.0 {
            // Penalty for creating a bin that is too small for the next item
            score += 10.0 * (1.0 - (post_res / next_item));
        }
    }

    // Coupling with mean_residual: If this bin is significantly emptier than the average,
    // we penalize it to encourage packing into denser bins (Best Fit/First Fit hybrid).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation * (1.0 - progress);

    // If this is the only bin that can fit the item, give it a significant bonus to 
    // prioritize using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable fragments (Dead Space minimization)
    // If post_residual is < 10, it's likely unusable as the smallest item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Prefer filling bins to specific thresholds based on capacity fractions
    // Penalize bins that leave remaining space in the "uncomfortable" mid-range (30-50)
    if post_residual >= 30 && post_residual <= 50 {
        score += 15.0;
    }

    // 3. Lookahead Integration: If next_item_size fits in post_residual, prioritize this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Further reward if it leaves a near-perfect fit (residual < 5)
        if post_residual - next_item_size < 5 {
            score -= 10.0;
        }
    }

    // 4. Scarcity/Fitting Logic:
    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // strongly incentivize using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global State Balancing:
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
        // Penalize opening a new bin if we are near the end of the stream
        let progress = step_index as f64 / total_items as f64;
        score += progress * 10.0;
    }

    // 6. Mean Residual Alignment:
    // Penalize bins that deviate significantly from the mean_residual of current bins
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize residuals that are too small to fit future items.
    // If the post_residual is positive but smaller than the smallest likely item (e.g., 10), 
    // it creates 'fragmentation'. We penalize this heavily to favor tighter fits.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Integration: If the next item could fit into this post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the current open bins are already full.
    // If this is a new bin (bin_residual == bin_capacity), add a penalty proportional to the 
    // number of bins currently open to discourage unnecessary bin proliferation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // reduce the score to ensure it is chosen over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Global Efficiency: If the current bin's mean residual is significantly higher than 
    // the post_residual, it implies we are consolidating space.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We normalize this by the bin_capacity to keep the base score in [0, 1].
    score = score / bin_capacity as f64;

    // 2. Dead Space Penalty: If post_residual is small but > 0, it's often wasted.
    // If it's very small (e.g., < 10), it's hard to fill, so penalize it.
    if post_residual > 0 && post_residual < 15 {
        score += 0.4;
    }

    // 3. Lookahead Synergy: If post_residual can fit the next item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5;
        // Further reward if it's a "perfect" fit for the next item.
        if post_residual == next_item_size {
            score -= 0.3;
        }
    }

    // 4. Scarcity/Congestion Control:
    // If fitting_bins_count is low, we are running out of options for this item.
    // Force usage of existing bins to avoid opening new ones prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.6;
    }

    // 5. New Bin Aversion:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 2.0; 
        } else {
            score -= 0.1;
        }
    }

    // 6. Global Trend adjustment:
    // As we near the end of the stream (step_index / total_items -> 1.0),
    // prioritize filling existing bins aggressively over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Start with the post_residual (Best Fit approach).
    let mut score = post_residual as f64;

    // Penalty for creating a bin that is "too empty" (under 20% full) relative to average.
    // If post_residual is very high, we penalize it unless it's a new bin.
    if bin_residual < bin_capacity && post_residual > 60 {
        score += 50.0;
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it.
    // If the next item cannot fit in current post_residual, apply a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // If this is the only bin that can fit the item, prioritize it heavily (Negative penalty).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // If it's a brand new bin (bin_residual == bin_capacity), penalize it based on progress.
    // We want to avoid opening new bins late in the stream if we have capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Base cost for opening a new bin is 35.0, increase if many bins are already open.
        score = 35.0 + (open_bins_count as f64 * 2.0) + (progress * 10.0);
    }

    // Reward bins that bring the residual closer to the global mean (balancing).
    // This helps prevent "outlier" bins with very small or very large residuals.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (lower post_residual).
    // We penalize the new bin creation exponentially as the stream progresses,
    // forcing the algorithm to be more conservative with new bins later on.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalty for opening a new bin:
        // 1. A base cost related to the average space we are leaving behind.
        // 2. An increasing cost over time to prevent early waste.
        // 3. A reduction if no other bins can fit the item (fitting_bins_count == 0).
        score = 25.0 + (mean_residual * 0.5) + (progress * 40.0);
        if fitting_bins_count > 0 {
            score += 30.0; // Heavy penalty for opening a new bin if an existing one works
        }
    } else {
        // For existing bins, we favor placements that leave a residual 
        // that is likely to accommodate the next item or a future large item.
        // If post_residual is very small (< 5), it might be "dead space" (hard to fill).
        if post_residual < 5 {
            score += 15.0 * (1.0 - progress);
        }

        // If the next item is large, prioritize bins that can actually accommodate it
        // after this placement.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }

        // Encourage balanced filling: penalize bins that deviate from the mean residual
        // to keep bin usage uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
