    // 6. Harmonic Class Logic: Prefer states that leave multiples of common item sizes (e.g., 20, 25, 50).
    // This helps align residual space with future item arrivals.
    let remainder_penalty = (post_residual % 20) as f64;
    score += remainder_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
