    // 2. Penalty for creating "dead space": if post_residual is small but > 0, it's often better
    //    to have a slightly larger residual if it accommodates the next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Excellent: The current bin can accommodate the next item.
            score -= 40.0;
        } else if post_residual > 0 && post_residual < 10 {
            // Poor: Creating a sliver of space that is likely unusable for future items.
            score += 25.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only pick it if we have no good choices.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the current open bins are very crowded (low mean_residual).
            score += 60.0 + (mean_residual * 0.5);
        }
    }

    // 4. Fitting count penalty:
    // If only one bin can fit the current item, prioritize it to avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Progression adjustment:
    // As we approach the end of the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
