pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual space (Best Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residuals too small for typical items (e.g., < 10) 
    // are often wasted. We penalize residuals in the [1, 9] range.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: If the next item fits into this post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state: If we have many open bins, prioritize filling existing bins (Best Fit).
    // If we have few open bins, we can afford to be more selective to keep space open.
    if fitting_bins_count > 0 {
        // If this is the only bin that fits the current item, prioritize it heavily
        // to avoid opening a new bin prematurely.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // If we are considering opening a NEW bin (bin_residual == bin_capacity),
        // apply a cost based on the current number of open bins and progression.
        if bin_residual == bin_capacity {
            // As the stream progresses, opening new bins becomes more expensive.
            score += 30.0 + (progress * 20.0) + (open_bins_count as f64 * 2.0);
        }
    }

    // Balance the mean residual: If this bin's post_residual is significantly 
    // higher than the average, it might be a poor fit.
