}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res_f = post_residual as f64;

    // Penalize small residuals that are too small to fit common future items (Dead Space)
    // We define a "dead zone" below 10 units.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        15.0 * (1.0 - (post_res_f / 10.0))
    } else {
        0.0
    };

    // Factor in lookahead: If next_item_size is large, avoid leaving a bin with 
    // barely enough space for current but not next.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        10.0 * (next_item_size as f64 / 100.0)
    } else {
        0.0
    };

    // Dynamic thresholding: as we reach the end of the stream (progress -> 1.0), 
    // be more aggressive about filling bins (Best Fit Decreasing style)
    let fill_urgency = (1.0 - progress) * post_res_f;

    // Favor bins that align with the current mean residual to keep bin states uniform
    let uniformity_bonus = (post_res_f - mean_residual).abs() * 0.5;

    // If this is a new bin, apply a significant base penalty that decays as the stream progresses
    // to prevent premature new bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (45.0 * (1.0 - progress * 0.5)) + (open_bins_count as f64 * 0.1)
    } else {
        0.0
    };

    // If this is the only bin that fits, prioritize it heavily
    let last_chance_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -50.0
    } else {
        0.0
    };

    let score = post_res_f + dead_space_penalty + lookahead_penalty + fill_urgency + uniformity_bonus + new_bin_penalty + last_chance_bonus;

