}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residuals that are too small to fit common items
    // but large enough to waste capacity. We define "unusable" as less than 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0;
    }

    // 3. Density Pressure: If we have many open bins, penalize opening a new one
    // or picking a bin that leaves too much empty space relative to the mean.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: higher when we have many open bins already
        score += (open_bins_count as f64 * 2.0) + 15.0;
    } else {
        // Reward bins that keep us close to the mean_residual to maintain compaction
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 4. Last Chance Logic: If this is the only bin that fits the current item,
    // we should prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize tight packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin heavily unless the total count is very low
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 2. Best-Fit logic: Prefer bins that leave the smallest residual (Best-Fit principle)
    // We already have post_residual as the base, which naturally favors smaller gaps.

    // 3. Lookahead Matching: If the next item fits into the current post_residual, 
    // significantly reward this placement to chain pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if it is an almost perfect fit for the next item
        if (post_residual - next_item_size) < 5 {
            score -= 15.0;
        }
    }

    // 4. Avoid "Small Gap" traps: Penalize residuals that are too small to fit any common item (e.g., < 10)
    // unless it is a perfect fit (post_residual == 0).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. Balance across bins: Penalize bins that deviate too far from the mean residual
    // to keep bins roughly at the same fill level.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // 7. Progress-based scaling: As the stream nears the end, be more aggressive with packing
    // to minimize the number of trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}
